    const f = this.fadeEl
    if (!f) return
    f.classList.toggle('white', white)
    f.classList.add('on')
    return new Promise(resolve => setTimeout(() => {
      f.style.transition = 'none'
      f.classList.remove('on')
      void f.offsetWidth
      f.style.transition = ''
      setTimeout(resolve, Math.min(ms, 400))
    }, ms))
  }

