const palette = zone.palette
const colorAt = (x, z, h) => {
  if (zone.isWater?.(x, z)) return palette.water
  const v = Math.max(0, Math.min(1, (h + 3) / 16))
  const base = new THREEColor(palette.ground)
  const alt = new THREEColor(palette.ground2)
  const rock = new THREEColor(palette.rock)
  let r, g, b
  if (v > .55) { r = rock.r; g = rock.g; b = rock.b } else { r = base.r + (alt.r - base.r) * v; g = base.g + (alt.g - base.g) * v; b = base.b + (alt.b - base.b) * v }
  const shade = .55 + .45 * Math.max(0, Math.min(1, (h + 3) / 12))
  return [r * 255 * shade, g * 255 * shade, b * 255 * shade]
}

input.newString:
const palette = zone.palette
const rgb = n => [(n >> 16) & 255, (n >> 8) & 255, n & 255]
const colorAt = (x, z, h) => {
  const shade = .55 + .45 * Math.max(0, Math.min(1, (h + 3) / 12))
  if (zone.isWater?.(x, z)) return rgb(palette.water).map(c => c * .9)
  const v = Math.max(0, Math.min(1, (h + 3) / 16))
  if (v > .55) return rgb(palette.rock).map(c => c * shade)
  const base = rgb(palette.ground), alt = rgb(palette.ground2)
  return [
    (base[0] + (alt[0] - base[0]) * v) * shade,
    (base[1] + (alt[1] - base[1]) * v) * shade,
    (base[2] + (alt[2] - base[2]) * v) * shade
  ]
}

