      body.add(leaf)
    }
    root.userData.rig = { body, head, baseY: 0 }
  } else if (def.model === 'bird') {
    const b = mesh(new THREE.SphereGeometry(.28, 8, 6), m, 0, 1.2, 0); b.scale.set(.8, .8, 1.1); body.add(b)
    const head = mesh(new THREE.SphereGeometry(.16, 7, 6), m, 0, 1.48, .22); body.add(head)
    body.add(mesh(new THREE.ConeGeometry(.05, .18, 4), a, 0, 1.45, .42).rotateX(Math.PI / 2))
    const wings = []
    for (const side of [-1, 1]) {
      const wing = group(side * .2, 1.28, 0)
      const w1 = mesh(new THREE.ConeGeometry(.14, .75, 4), a, side * .32, .05, 0); w1.rotation.z = side * 1.1
      wing.add(w1)
      body.add(wing); wings.push(wing)
    }
    for (let i = 0; i < 2; i++) {
      const tail = mesh(new THREE.ConeGeometry(.08, .42, 4), a, 0, 1.12 - i * .12, -.35 - i * .08)
      tail.rotation.x = -1.2
      body.add(tail)
    }
    root.userData.rig = { body, head, wings, baseY: 0 }
  } else if (def.model === 'salamander') {
    const b = mesh(new THREE.SphereGeometry(.34, 8, 6), m, 0, .62, 0); b.scale.set(.75, .55, 1.3); body.add(b)
    const head = mesh(new THREE.SphereGeometry(.2, 7, 6), m, 0, .7, .42); body.add(head)
    for (const x of [-.08, .08]) body.add(mesh(new THREE.SphereGeometry(.028, 5, 4), glowMat(accent, .9), x, .75, .59, false))
    const tail = mesh(new THREE.ConeGeometry(.12, .7, 5), m, 0, .62, -.55); tail.rotation.x = -Math.PI / 2; body.add(tail)
    for (const [x, z] of [[-.22, .24], [.22, .24], [-.22, -.22], [.22, -.22]]) {
      body.add(mesh(new THREE.CylinderGeometry(.045, .035, .25, 4), m, x, .4, z))
    }
    for (let i = 0; i < 5; i++) {
      const flame = new THREE.Mesh(new THREE.ConeGeometry(.05, .24, 4), glowMat(accent, .5))
      flame.position.set((i - 2) * .11, .98 + (i % 2) * .1, -.1 + i * .06)
      body.add(flame)
    }
    root.userData.rig = { body, head, baseY: 0 }
  } else if (def.model === 'cat') {
    const b = mesh(new THREE.SphereGeometry(.28, 8, 6), m, 0, .58, 0); b.scale.set(.8, .7, 1.3); body.add(b)
    const head = group(0, .82, .36)
    head.add(mesh(new THREE.SphereGeometry(.18, 7, 6), m))
    for (const x of [-.1, .1]) {
      const ear = mesh(new THREE.ConeGeometry(.055, .16, 4), m, x, .17, 0); head.add(ear)
      head.add(mesh(new THREE.SphereGeometry(.022, 5, 4), glowMat(accent, .9), x * .7, .02, .15, false))
    }
    body.add(head)
    for (const [x, z] of [[-.16, .24], [.16, .24], [-.16, -.22], [.16, -.22]]) {
      body.add(mesh(new THREE.CylinderGeometry(.04, .03, .35, 4), m, x, .3, z))
    }
    const tail = mesh(new THREE.ConeGeometry(.05, .65, 4), m, .18, .82, -.35); tail.rotation.x = -1.1; tail.rotation.z = .4; body.add(tail)
    root.userData.rig = { body, head, baseY: 0 }
  } else if (def.model === 'turtle') {
    const shell = mesh(new THREE.SphereGeometry(.55, 8, 6, 0, Math.PI * 2, 0, Math.PI / 2), std(color, { roughness: .9 }), 0, .55, 0)
    shell.scale.set(1.05, .75, 1.25)
    body.add(shell)
    body.add(mesh(new THREE.TorusGeometry(.45, .05, 4, 14), a, 0, .58, 0).rotateX(Math.PI / 2))
    const head = mesh(new THREE.SphereGeometry(.16, 7, 6), m, 0, .48, .56); body.add(head)
    for (const [x, z] of [[-.34, .3], [.34, .3], [-.34, -.28], [.34, -.28]]) {
      body.add(mesh(new THREE.CylinderGeometry(.09, .075, .22, 4), m, x, .25, z))
    }
    root.userData.rig = { body, head, baseY: 0 }
  } else if (def.model === 'jelly') {
    const bell = mesh(new THREE.SphereGeometry(.5, 10, 8, 0, Math.PI * 2, 0, Math.PI * .62), std(color, { transparent: true, opacity: .75, emissive: color, emissiveIntensity: .2 }), 0, 1.45, 0)
    bell.scale.y = .9
    body.add(bell)
    for (let i = 0; i < 7; i++) {
      const t = group(Math.cos(i / 7 * Math.PI * 2) * .3, 1.25, Math.sin(i / 7 * Math.PI * 2) * .3)
      const tent = mesh(new THREE.CylinderGeometry(.025, .012, .85 + (i % 3) * .18, 4), std(accent, { transparent: true, opacity: .55, emissive: accent, emissiveIntensity: .3 }))
      tent.position.y = -.42
      t.add(tent); t.userData.phase = i; body.add(t)
    }
    const core = new THREE.Mesh(new THREE.IcosahedronGeometry(.16, 0), glowMat(0xffffff, .7)); core.position.y = 1.42; body.add(core)
    root.userData.rig = { body, head: bell, baseY: 0 }
  } else {
    // Dragón de bolsillo
    const b = mesh(new THREE.SphereGeometry(.34, 8, 6), m, 0, .9, 0); b.scale.set(.8, .85, 1.15); body.add(b)
    const head = group(0, 1.22, .38)
    head.add(mesh(new THREE.SphereGeometry(.2, 8, 6), m))
    head.add(mesh(new THREE.ConeGeometry(.1, .3, 5), m, 0, -.03, .23).rotateX(Math.PI / 2))
    for (const x of [-.1, .1]) head.add(mesh(new THREE.ConeGeometry(.035, .18, 4), a, x, .2, -.04))
    for (const x of [-.07, .07]) head.add(mesh(new THREE.SphereGeometry(.024, 5, 4), glowMat(0xffffff, .95), x, .04, .18, false))
    body.add(head)
    const wings = []
    for (const side of [-1, 1]) {
      const wing = group(side * .22, 1.0, 0)
      const w = mesh(new THREE.ConeGeometry(.2, .6, 3), std(accent, { transparent: true, opacity: .6, emissive: accent, emissiveIntensity: .3 }), side * .3, .08, 0)
      w.rotation.z = side * 1.2
      wing.add(w); body.add(wing); wings.push(wing)
    }
    const tail = mesh(new THREE.ConeGeometry(.08, .75, 5), m, 0, .78, -.55); tail.rotation.x = -1.4; body.add(tail)
    for (let i = 0; i < 3; i++) {
      const sh = new THREE.Mesh(new THREE.OctahedronGeometry(.06), glowMat(accent, .6))
      sh.position.set((i - 1) * .3, 1.4 + i * .12, -.2)
      body.add(sh)
    }
    root.userData.rig = { body, head, wings, baseY: 0 }
  }
  root.scale.setScalar(1.15)
  root.userData.kind = 'creature'
  return root
}

export function createNameTag(text, sub = '', accent = 0xe4c27c) {
  const canvas = document.createElement('canvas')
  canvas.width = 512; canvas.height = 160
  const ctx = canvas.getContext('2d')
  ctx.clearRect(0, 0, 512, 160)
  ctx.textAlign = 'center'
  ctx.font = '600 44px Cinzel, serif'
  ctx.fillStyle = '#f2e7cc'
  ctx.shadowColor = 'rgba(0,0,0,.9)'; ctx.shadowBlur = 12
  ctx.fillText(text, 256, 62)
  ctx.font = '500 26px "Trebuchet MS", sans-serif'
  ctx.fillStyle = '#' + accent.toString(16).padStart(6, '0')
  ctx.fillText(sub, 256, 104)
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, opacity: .96 })
  const sprite = new THREE.Sprite(mat)
  sprite.scale.set(2.4, .75, 1)
  return sprite
}

export function createSword(itemId, scale = 1) { return swordMesh(itemId, scale) }

export function makeGlow(color, radius = .4) {
  const mat = glowMat(color, .4)
  return new THREE.Mesh(new THREE.SphereGeometry(radius, 8, 6), mat)
}

import * as THREE from 'three'

const rand = (a, b) => a + Math.random() * (b - a)

function additive(color, opacity = .9) {
  return new THREE.PointsMaterial({
    color, size: .13, transparent: true, opacity, depthWrite: false,
    blending: THREE.AdditiveBlending, sizeAttenuation: true
  })
}

export class Effects {
  constructor(game) {
    this.game = game
    this.bursts = []
    this.rings = []
    this.slashes = []
    this.beams = []
    this.auras = []
    this.projectiles = []
  }

  burst(pos, color = 0xffe0a8, count = 18, opts = {}) {
    const n = Math.max(4, count)
    const positions = new Float32Array(n * 3)
    const velocities = []
    for (let i = 0; i < n; i++) {
      positions[i * 3] = pos.x + rand(-.15, .15)
      positions[i * 3 + 1] = pos.y + rand(-.1, .2)
      positions[i * 3 + 2] = pos.z + rand(-.15, .15)
      const a = Math.random() * Math.PI * 2
      const up = rand(.2, 1.1)
      const sp = rand(opts.speedMin ?? .8, opts.speed ?? 3.4)
      velocities.push(new THREE.Vector3(Math.cos(a) * sp, up * sp, Math.sin(a) * sp))
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    const mat = additive(color, opts.opacity ?? .9)
    mat.size = opts.size ?? .13
    const points = new THREE.Points(geo, mat)
    points.frustumCulled = false
    this.game.scene.add(points)
    this.bursts.push({
      points, velocities, life: 0, maxLife: opts.life ?? .7,
      gravity: opts.gravity ?? -3.2, drag: opts.drag ?? .96
    })
  }

  ring(pos, color = 0xffe0a8, radius = 2.4, opts = {}) {
    const geo = new THREE.RingGeometry(.18, .34, 32)
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .85, blending: THREE.AdditiveBlending, side: THREE.DoubleSide, depthWrite: false })
    const m = new THREE.Mesh(geo, mat)
    m.rotation.x = -Math.PI / 2
    m.position.copy(pos)
    m.position.y += .06
    this.game.scene.add(m)
    this.rings.push({ mesh: m, life: 0, maxLife: opts.life ?? .65, radius, color })
    return m
  }

  slash(pos, yaw, color = 0xffd9a0, scale = 1.5) {
    const geo = new THREE.RingGeometry(scale * .45, scale * 1.1, 24, 1, -Math.PI * .32, Math.PI * .64)
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .8, blending: THREE.AdditiveBlending, side: THREE.DoubleSide, depthWrite: false })
    const m = new THREE.Mesh(geo, mat)
    m.rotation.x = -Math.PI / 2
    m.rotation.z = -yaw + Math.PI / 2
    m.position.copy(pos)
    m.position.y += 1.0
    this.game.scene.add(m)
    this.slashes.push({ mesh: m, life: 0, maxLife: .26 })
  }

  beam(from, to, color = 0x9fe8ff, width = .09) {
    const dir = new THREE.Vector3().subVectors(to, from)
    const len = dir.length()
    const geo = new THREE.CylinderGeometry(width, width * .45, len, 6, 1, true)
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .9, blending: THREE.AdditiveBlending, depthWrite: false })
    const m = new THREE.Mesh(geo, mat)
    m.position.copy(from).add(to).multiplyScalar(.5)
    m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize())
    this.game.scene.add(m)
    this.beams.push({ mesh: m, life: 0, maxLife: .3 })
  }

  aura(target, color = 0x9fe8ff, radius = 1.1) {
    const g = new THREE.Group()
    const ring1 = new THREE.Mesh(new THREE.TorusGeometry(radius, .025, 4, 28), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .65, blending: THREE.AdditiveBlending, depthWrite: false }))
    ring1.rotation.x = Math.PI / 2
    const ring2 = ring1.clone()
    ring2.rotation.z = Math.PI / 3
    ring2.rotation.x = Math.PI / 3
    g.add(ring1, ring2)
    const light = new THREE.PointLight(color, .7, radius * 4)
    g.add(light)
    target.add(g)
    const item = { group: g, target, life: 0, maxLife: 1e9, color, radius }
    this.auras.push(item)
    return item
  }

  removeAura(item) {
    if (!item) return
    item.target?.remove(item.group)
    item.group.traverse(o => { o.geometry?.dispose?.(); o.material?.dispose?.() })
    const i = this.auras.indexOf(item)
    if (i >= 0) this.auras.splice(i, 1)
  }

  projectile(opts) {
    const color = opts.color ?? 0xff8a4c
    const radius = opts.radius ?? .22
    const mesh = new THREE.Mesh(
      new THREE.IcosahedronGeometry(radius, 0),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .95, blending: THREE.AdditiveBlending, depthWrite: false })
    )
    mesh.position.copy(opts.pos)
    const light = new THREE.PointLight(color, .8, 4)
    mesh.add(light)
    const halo = new THREE.Mesh(new THREE.SphereGeometry(radius * 1.8, 8, 6), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .16, blending: THREE.AdditiveBlending, depthWrite: false }))
    mesh.add(halo)
    this.game.scene.add(mesh)
    const dir = opts.dir.clone().normalize()
    const p = {
      mesh, pos: mesh.position, dir, speed: opts.speed ?? 18, damage: opts.damage ?? 10,
      owner: opts.owner ?? 'enemy', life: 0, maxLife: opts.life ?? 3, radius,
      onHit: opts.onHit, homing: opts.homing ?? 0, target: opts.target || null, color
    }
    this.projectiles.push(p)
    return p
  }

  update(dt) {
    const game = this.game
    for (let i = this.bursts.length - 1; i >= 0; i--) {
      const b = this.bursts[i]
      b.life += dt
      const arr = b.points.geometry.attributes.position.array
      for (let j = 0; j < b.velocities.length; j++) {
        const v = b.velocities[j]
        v.y += b.gravity * dt
        v.multiplyScalar(Math.pow(b.drag, dt * 60))
        arr[j * 3] += v.x * dt
        arr[j * 3 + 1] += v.y * dt
        arr[j * 3 + 2] += v.z * dt
      }
      b.points.geometry.attributes.position.needsUpdate = true
      b.points.material.opacity = Math.max(0, 1 - b.life / b.maxLife)
      if (b.life >= b.maxLife) {
        game.scene.remove(b.points)
        b.points.geometry.dispose(); b.points.material.dispose()
        this.bursts.splice(i, 1)
      }
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i]
      r.life += dt
      const t = Math.min(1, r.life / r.maxLife)
      r.mesh.scale.setScalar(.6 + t * r.radius)
      r.mesh.material.opacity = (1 - t) * .7
      if (t >= 1) {
        game.scene.remove(r.mesh); r.mesh.geometry.dispose(); r.mesh.material.dispose()
        this.rings.splice(i, 1)
      }
    }
    for (let i = this.slashes.length - 1; i >= 0; i--) {
      const s = this.slashes[i]
      s.life += dt
      const t = Math.min(1, s.life / s.maxLife)
      s.mesh.material.opacity = (1 - t) * .85
      s.mesh.scale.setScalar(1 + t * .25)
      if (t >= 1) {
        game.scene.remove(s.mesh); s.mesh.geometry.dispose(); s.mesh.material.dispose()
        this.slashes.splice(i, 1)
      }
    }
    for (let i = this.beams.length - 1; i >= 0; i--) {
      const b = this.beams[i]
      b.life += dt
      const t = Math.min(1, b.life / b.maxLife)
      b.mesh.material.opacity = (1 - t) * .9
      if (t >= 1) {
        game.scene.remove(b.mesh); b.mesh.geometry.dispose(); b.mesh.material.dispose()
        this.beams.splice(i, 1)
      }
    }
    for (const a of this.auras) {
      a.life += dt
      a.group.rotation.y += dt * 1.3
      a.group.children[0].rotation.z += dt * .7
      a.group.children[1].rotation.x += dt * .5
    }
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i]
      p.life += dt
      if (p.homing && p.target?.alive) {
        const want = new THREE.Vector3(p.target.pos.x, p.target.pos.y + 1, p.target.pos.z).sub(p.pos).normalize()
        p.dir.lerp(want, Math.min(1, p.homing * dt)).normalize()
      }
      p.pos.addScaledVector(p.dir, p.speed * dt)
      if (p.life >= p.maxLife) {
        this.removeProjectile(i); continue
      }
      if (p.owner === 'enemy' && game.player && !game.player.dead) {
        const d = Math.hypot(p.pos.x - game.player.pos.x, p.pos.z - game.player.pos.z)
        const dy = Math.abs(p.pos.y - (game.player.pos.y + 1))
        if (d < .75 + p.radius && dy < 1.4) {
          p.onHit?.(game.player)
          game.player.takeDamage(p.damage, { ranged: true })
          game.fx.burst(p.pos, p.color, 10, { speed: 2 })
          this.removeProjectile(i); continue
        }
      } else if (p.owner === 'player' && game.world) {
        for (const e of game.world.enemies) {
          if (!e.alive) continue
          const d = Math.hypot(p.pos.x - e.pos.x, p.pos.z - e.pos.z)
          if (d < e.def.radius + p.radius && Math.abs(p.pos.y - (e.pos.y + 1)) < 1.6) {
            e.takeDamage(p.damage, { source: 'skill' })
            game.fx.burst(p.pos, p.color, 12, { speed: 2.4 })
            p.onHit?.(e)
            this.removeProjectile(i); break
          }
        }
      }
    }
  }

  removeProjectile(i) {
    const p = this.projectiles[i]
    if (!p) return
    this.game.scene.remove(p.mesh)
    p.mesh.traverse(o => { o.geometry?.dispose?.(); o.material?.dispose?.() })
    this.projectiles.splice(i, 1)
  }

  clearProjectiles() {
    for (let i = this.projectiles.length - 1; i >= 0; i--) this.removeProjectile(i)
  }

  dispose() {
    for (const b of this.bursts) { this.game.scene?.remove(b.points); b.points.geometry.dispose(); b.points.material.dispose() }
    for (const r of this.rings) { this.game.scene?.remove(r.mesh); r.mesh.geometry.dispose(); r.mesh.material.dispose() }
    for (const s of this.slashes) { this.game.scene?.remove(s.mesh); s.mesh.geometry.dispose(); s.mesh.material.dispose() }
    for (const b of this.beams) { this.game.scene?.remove(b.mesh); b.mesh.geometry.dispose(); b.mesh.material.dispose() }
    for (const a of [...this.auras]) this.removeAura(a)
    this.clearProjectiles()
    this.bursts = []; this.rings = []; this.slashes = []; this.beams = []
  }
}

import * as THREE from 'three'
import { derive, xpForLevel } from '../core/stats.js'
import { JURAMENTOS, ITEMS } from '../data/items.js'
import { CREATURES } from '../data/creatures.js'
import { createHumanoid, createCreatureModel } from '../world/models.js'
import { clamp, dampAngle, TAU } from '../utils/math.js'

const HALF_PI = Math.PI / 2

export class Player {
  constructor(game, save) {
    this.game = game
    this.save = save
    this.pos = new THREE.Vector3()
    this.velocity = new THREE.Vector3()
    this.derived = derive(save.stats, save.equipment, save.level)
    this.hp = this.derived.hp
    this.mp = this.derived.mp
    this.stamina = this.derived.stamina
    this.dead = false
    this.facing = Math.PI
    this.moveSpeed = 0
    this.cooldowns = { skill1: 0, skill2: 0, creature: 0, potion: 0, capture: 0 }
    this.skillData = { cd1: 8, cd2: 16 }
    this.creatureCooldown = 14
    this.effects = []
    this.shield = 0
    this.blocking = false
    this.blockTime = 0
    this.parryReady = 0
    this.iFrames = 0
    this.dodgeTime = 0
    this.dodgeDir = new THREE.Vector3()
    this.attackTimer = 0
    this.attackHitAt = 0
    this.attackDidHit = false
    this.comboIndex = 0
    this.comboTimer = 0
    this.comboQueued = false
    this.attackCD = 0
    this.hurtFlash = 0
    this.captureTarget = null
    this.companion = null
    this.companionData = null
    this.companionOffset = new THREE.Vector3(1.3, 0, 1.1)
    this.auraItem = null
    this.outOfCombat = 0
    this.walkPhase = 0
    this.tmp = new THREE.Vector3()
    this.beamCooldown = 0
    this.brasalTick = 0
    this.mesh = this.buildMesh()
  }

  buildMesh() {
    const mesh = createHumanoid({
      appearance: this.save.appearance,
      equipment: this.save.equipment,
      scale: 1,
      weaponScale: 1.05
    })
    mesh.position.copy(this.pos)
    mesh.rotation.y = this.facing
    return mesh
  }

  rebuildMesh() {
    const old = this.mesh
    const parent = old?.parent
    const next = this.buildMesh()
    next.position.copy(old?.position || this.pos)
    next.rotation.copy(old?.rotation || new THREE.Euler(0, this.facing, 0))
    if (parent) { parent.remove(old); parent.add(next) }
    old?.traverse(o => {
      if (o.geometry) o.geometry.dispose()
      if (o.material && !Array.isArray(o.material)) o.material.dispose()
    })
    this.mesh = next
    if (this.save.activeCreature) this.setCompanion(this.save.activeCreature)
  }

  place(x, z) {
    const zone = this.game.world?.zone
    this.pos.set(x, zone ? zone.heightAt(x, z) + .03 : 0, z)
    this.mesh.position.copy(this.pos)
    this.velocity.set(0, 0, 0)
    this.game.cameraFocus?.copy(this.pos)
  }

  passiveMods() {
    const active = this.save.activeCreature
    const def = active ? CREATURES[active] : null
    const mods = { hp: 1, mp: 1, speed: 1, defense: 0, crit: 0, manaRegen: 1, regen: 0, attack: 1 }
    if (!def) return mods
    if (active === 'bramiel') mods.defense += .1
    if (active === 'grimpola') mods.speed += .05
    if (active === 'umbrino') mods.crit += .08
    if (active === 'cineronte') mods.hp += .18
    if (active === 'petreluz') mods.manaRegen += .15
    if (active === 'celemn') { mods.hp += .1; mods.mp += .1; mods.attack += .1; mods.defense += .1; mods.speed += .1; mods.crit += .1 }
    return mods
  }

  recalc(full = false) {
    const base = derive(this.save.stats, this.save.equipment, this.save.level)
    const mods = this.passiveMods()
    base.hp = Math.round(base.hp * mods.hp)
    base.mp = Math.round(base.mp * mods.mp)
    base.attack *= mods.attack
    base.speed *= mods.speed
    base.reduction = Math.min(.82, base.reduction + mods.defense)
    base.crit = Math.min(.8, base.crit + mods.crit)
    base.manaRegen *= mods.manaRegen
    this.derived = base
    if (full) { this.hp = base.hp; this.mp = base.mp; this.stamina = base.stamina }
    else {
      this.hp = Math.min(this.hp, base.hp)
      this.mp = Math.min(this.mp, base.mp)
      this.stamina = Math.min(this.stamina, base.stamina)
    }
    this.game.ui?.refreshHUD?.()
  }

  setCompanion(id) {
    if (this.companion) {
      this.game.scene?.remove(this.companion)
      this.companion.traverse(o => { o.geometry?.dispose?.(); o.material?.dispose?.() })
      this.companion = null
    }
    const owned = this.save.creatures.find(c => c.id === id)
    const def = CREATURES[id]
    if (!owned || !def) { this.companionData = null; return }
    const model = createCreatureModel(def)
    model.scale.setScalar(.58)
    const lvl = owned.level || 1
    model.userData.phase = Math.random() * TAU
    const light = new THREE.PointLight(def.color, .45, 3.4)
    light.position.y = 1
    model.add(light)
    this.game.scene?.add(model)
    this.companion = model
    this.companionData = { def, level: lvl, id }
    this.recalc()
  }

  update(dt) {
    if (this.dead) return
    const game = this.game
    if (game.state !== 'playing') { this.animate(dt, true); return }
    dt = Math.min(dt, .05)

    this.tickTimers(dt)
    this.updateEffects(dt)
    const input = game.input
    const axis = input.axis()
    const yaw = game.cameraYaw
    const forward = { x: -Math.sin(yaw), z: -Math.cos(yaw) }
    const right = { x: Math.cos(yaw), z: -Math.sin(yaw) }
    let mx = right.x * axis.x + forward.x * (-axis.y)
    let mz = right.z * axis.x + forward.z * (-axis.y)
    const mlen = Math.hypot(mx, mz)
    if (mlen > .01) { mx /= mlen; mz /= mlen }
    const moving = mlen > .05

    let speed = this.derived.speed
    if (this.blocking) speed *= .44
    if (this.attackTimer > 0) speed *= .16
    if (this.dodgeTime > 0) speed = 0

    if (this.dodgeTime > 0) {
      this.pos.x += this.dodgeDir.x * 13.5 * dt
      this.pos.z += this.dodgeDir.z * 13.5 * dt
      this.facing = Math.atan2(this.dodgeDir.x, this.dodgeDir.z)
    } else if (moving) {
      this.pos.x += mx * speed * dt
      this.pos.z += mz * speed * dt
      this.facing = dampAngle(this.facing, Math.atan2(mx, mz), 14, dt)
      this.moveSpeed = speed
    } else {
      this.moveSpeed = 0
      if (this.attackTimer > 0) this.facing = dampAngle(this.facing, yaw + Math.PI, 16, dt)
    }

    this.clampPosition()
    const zone = game.world?.zone
    const ground = zone ? zone.heightAt(this.pos.x, this.pos.z) : 0
    this.pos.y = ground + .03
    this.mesh.position.copy(this.pos)
    this.mesh.rotation.y = this.facing

    // Animación de ataque
    if (this.attackTimer > 0) {
      this.attackTimer -= dt
      const spent = (this.comboIndex === 2 ? .46 : .34) - this.attackTimer
      if (!this.attackDidHit && spent >= this.attackHitAt) {
        this.attackDidHit = true
        this.performHit()
      }
      if (this.attackTimer <= 0) {
        this.attackTimer = 0
        if (this.comboQueued && this.comboIndex < 2) this.startAttack(true)
        else this.attackCD = .08
      }
    } else if (this.comboTimer > 0) {
      this.comboTimer -= dt
      if (this.comboTimer <= 0) this.comboIndex = 0
    }

    if (this.blocking && this.parryReady > 0) this.parryReady -= dt
    if (this.iFrames > 0) this.iFrames -= dt
    if (this.dodgeTime > 0) {
      this.dodgeTime -= dt
      if (this.dodgeTime <= 0) this.dodgeTime = 0
    }

    // Regeneración
    this.outOfCombat += dt
    if (this.outOfCombat > 4.5) {
      this.hp = Math.min(this.derived.hp, this.hp + this.derived.hpRegen * dt)
      const regen = this.passiveMods().regen + (this.save.activeCreature === 'lumifin' ? 2 : 0)
      if (regen) this.hp = Math.min(this.derived.hp, this.hp + regen * dt)
    }
    this.mp = Math.min(this.derived.mp, this.mp + this.derived.manaRegen * dt)
    this.stamina = Math.min(this.derived.stamina, this.stamina + this.derived.staminaRegen * (this.blocking ? .18 : 1) * dt)

    this.updateCompanion(dt)
    this.updateAura()
    this.updateCaptureTarget()
    this.updateBrasalAura(dt)
    this.animate(dt)
  }

  tickTimers(dt) {
    for (const k of Object.keys(this.cooldowns)) this.cooldowns[k] = Math.max(0, this.cooldowns[k] - dt)
    if (this.attackCD > 0) this.attackCD -= dt
  }

  updateEffects(dt) {
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const e = this.effects[i]
      e.time -= dt
      if (e.time <= 0) {
        if (e.id === 'shield') this.shield = 0
        this.effects.splice(i, 1)
      }
    }
  }

  clampPosition() {
    const world = this.game.world
    if (!world) return
    const zone = world.zone
    const b = zone.bounds - 4
    this.pos.x = clamp(this.pos.x, -b, b)
    this.pos.z = clamp(this.pos.z, -b, b)
    if (zone.isWater?.(this.pos.x, this.pos.z)) {
      const h = zone.heightAt(this.pos.x, this.pos.z)
      if (h < (zone.id === 'drakmor' ? -1.8 : -2.5)) {
        this.pos.x -= this.velocity.x * .01
        this.pos.z -= this.velocity.z * .01
      }
    }
    const c = world.resolveCollision?.(this.pos.x, this.pos.z, .55)
    if (c) { this.pos.x = c.x; this.pos.z = c.z }
    if (world.bossArenaLock) {
      const a = world.bossArenaLock
      const d = Math.hypot(this.pos.x - a.x, this.pos.z - a.z)
      if (d > a.radius) {
        const k = a.radius / d
        this.pos.x = a.x + (this.pos.x - a.x) * k
        this.pos.z = a.z + (this.pos.z - a.z) * k
      }
    }
  }

  updateCaptureTarget() {
    this.captureTarget = null
    if (!this.game.world) return
    let best = null, bestD = 8
    for (const c of this.game.world.creatureSpawns) {
      if (c.caught || c.dead) continue
      const d = Math.hypot(c.pos.x - this.pos.x, c.pos.z - this.pos.z)
      if (d < bestD && c.hp / c.maxHp <= .45) { best = c; bestD = d }
    }
    this.captureTarget = best
  }

  updateCompanion(dt) {
    if (!this.companion) return
    const t = performance.now() * .001
    const side = Math.sin(t * .7 + this.companion.userData.phase) * .45
    const targetX = this.pos.x + Math.cos(this.facing) * this.companionOffset.z + Math.sin(this.facing) * (1.2 + side)
    const targetZ = this.pos.z - Math.sin(this.facing) * this.companionOffset.z + Math.cos(this.facing) * (1.2 + side)
    const ground = this.game.world?.zone?.heightAt(targetX, targetZ) ?? 0
    const targetY = ground + 1.15 + Math.sin(t * 2.2 + (this.companion.userData.phase || 0)) * .12
    this.companion.position.x += (targetX - this.companion.position.x) * Math.min(1, dt * 3.4)
    this.companion.position.z += (targetZ - this.companion.position.z) * Math.min(1, dt * 3.4)
    this.companion.position.y += (targetY - this.companion.position.y) * Math.min(1, dt * 4.2)
    this.companion.rotation.y = dampAngle(this.companion.rotation.y, this.facing, 6, dt)
    const rig = this.companion.userData.rig
    if (rig?.wings) rig.wings.forEach((w, i) => { w.rotation.z = Math.sin(t * 8 + i * Math.PI) * .35 })
    if (rig?.body) rig.body.position.y = Math.sin(t * 2.4) * .04
  }

  updateAura() {
    const shieldEffect = this.effects.find(e => e.id === 'shield' || e.id === 'bastion' || e.id === 'bark')
    if (shieldEffect && !this.auraItem) {
      this.auraItem = this.game.fx.aura(this.mesh, shieldEffect.color || 0x9fe8ff, 1.1)
    } else if (!shieldEffect && this.auraItem) {
      this.game.fx.removeAura(this.auraItem); this.auraItem = null
    }
  }

  updateBrasalAura(dt) {
    if (this.save.activeCreature !== 'brasal' || !this.game.world) return
    this.brasalTick += dt
    if (this.brasalTick < 1.1) return
    this.brasalTick = 0
    for (const e of this.game.world.enemies) {
      if (!e.alive) continue
      if (Math.hypot(e.pos.x - this.pos.x, e.pos.z - this.pos.z) < 3.8) e.takeDamage(4 + this.save.level * .7, { source: 'aura', silent: true })
    }
  }

  animate(dt, frozen = false) {
    const rig = this.mesh.userData.rig
    if (!rig) return
    const t = performance.now() * .001
    let speed = frozen ? 0 : this.moveSpeed
    if (this.dodgeTime > 0) speed = 12
    this.walkPhase += dt * (2.4 + speed * .72)
    const swing = Math.sin(this.walkPhase) * Math.min(.75, speed * .07)
    const bob = Math.abs(Math.sin(this.walkPhase * 2)) * Math.min(.06, speed * .006)
    rig.body.position.y = bob + (this.dead ? -.35 : 0)
    rig.legL.rotation.x = swing
    rig.legR.rotation.x = -swing
    rig.armL.rotation.x = -swing * .7
    rig.armR.rotation.x = swing * .35
    rig.armL.rotation.z = -.08
    rig.armR.rotation.z = .08
    rig.body.rotation.z = this.dodgeTime > 0 ? .25 : 0
    rig.head.rotation.y = Math.sin(t * .7) * .04
    rig.head.rotation.x = this.blocking ? .12 : 0

    if (this.attackTimer > 0) {
      const total = this.comboIndex === 2 ? .46 : .34
      const p = 1 - this.attackTimer / total
      const ang = this.comboIndex === 2
        ? -2.3 + p * 3.6
        : (this.comboIndex === 1 ? 1.8 - p * 3.4 : -1.4 + p * 2.9)
      rig.armR.rotation.x = ang
      rig.armR.rotation.z = -.45 + Math.sin(p * Math.PI) * .9
      rig.body.rotation.y = Math.sin(p * Math.PI) * (this.comboIndex === 2 ? .55 : .32)
    } else {
      rig.body.rotation.y = 0
    }
    if (this.blocking) {
      rig.armL.rotation.x = -1.2
      rig.armL.rotation.z = .8
      rig.armR.rotation.x = -.45
    }
    if (this.hurtFlash > 0) {
      this.hurtFlash -= dt
      this.mesh.traverse(o => { if (o.material?.emissive) o.material.emissive.setHex(0x6a1a14) })
    } else if (this.mesh.userData.lastFlash) {
      this.mesh.userData.lastFlash = false
      this.rebuildMaterialsEmission()
    }
  }

  rebuildMaterialsEmission() {
    this.mesh.traverse(o => {
      if (o.material?.emissive && o.material.userData.baseEmissive !== undefined) {
        o.material.emissive.setHex(o.material.userData.baseEmissive)
      }
    })
  }

  // ───────────── Acciones ─────────────
  startAttack(queued = false) {
    if (this.dead || this.attackCD > 0 || this.attackTimer > 0) return
    if (this.stamina < 5) { this.game.toast('Sin aguante para atacar.', '⚠'); return }
    if (!queued) {
      if (this.comboTimer > 0) this.comboIndex = (this.comboIndex + 1) % 3
      else this.comboIndex = 0
    } else this.comboIndex++
    this.stamina -= 5
    this.attackTimer = this.comboIndex === 2 ? .46 : .34
    this.attackHitAt = this.comboIndex === 2 ? .22 : .13
    this.attackDidHit = false
    this.comboQueued = false
    this.comboTimer = .9
    this.outOfCombat = 0
    this.game.audio?.sfx(this.comboIndex === 2 ? 'heavy' : 'swing')
    this.game.shakeCamera?.(this.comboIndex === 2 ? .08 : .035, .12)
  }

  queueCombo() {
    if (this.attackTimer > 0) {
      if (this.attackTimer < .24 && this.comboIndex < 2) this.comboQueued = true
      return true
    }
    return false
  }

  performHit() {
    const game = this.game
    const reach = this.comboIndex === 2 ? 3.1 : 2.45
    const arc = this.comboIndex === 2 ? Math.PI * .9 : Math.PI * .62
    const dmgBase = this.derived.attack * (this.comboIndex === 2 ? 1.85 : this.comboIndex === 1 ? 1.12 : 1)
    const origin = new THREE.Vector3(this.pos.x, this.pos.y + 1, this.pos.z)
    const dir = new THREE.Vector3(Math.sin(this.facing), 0, Math.cos(this.facing))
    game.fx.slash(this.pos, this.facing, this.comboIndex === 2 ? 0xffc46a : 0xffe6c0, this.comboIndex === 2 ? 2 : 1.45)
    let hits = 0
    for (const enemy of game.world?.enemies || []) {
      if (!enemy.alive) continue
      const to = new THREE.Vector3(enemy.pos.x - this.pos.x, 0, enemy.pos.z - this.pos.z)
      const d = to.length()
      if (d > reach + enemy.def.radius) continue
      to.normalize()
      const dot = dir.dot(to)
      if (dot < Math.cos(arc / 2)) continue
      const crit = Math.random() < this.derived.crit
      let dmg = dmgBase * (crit ? this.derived.critMult : 1) * (0.93 + Math.random() * .14)
      if (enemy.def.boss) dmg *= .92
      enemy.takeDamage(Math.round(dmg), { crit, source: 'player', dir: to.clone(), combo: this.comboIndex })
      hits++
    }
    if (hits) {
      this.outOfCombat = 0
      game.hitStop = Math.max(game.hitStop, this.comboIndex === 2 ? .11 : .055)
      game.shakeCamera?.(this.comboIndex === 2 ? .24 : .12, .18)
      game.audio?.sfx('hit')
      if (this.comboIndex === 2) game.fx.ring(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0xffd28a, 2.8, { life: .45 })
    }
  }

  dodge() {
    if (this.dead || this.dodgeTime > 0 || this.stamina < this.derived.dodgeCost) return
    const axis = this.game.input.axis()
    let dx = 0, dz = 0
    if (Math.abs(axis.x) + Math.abs(axis.y) > .1) {
      const yaw = this.game.cameraYaw
      const forward = { x: -Math.sin(yaw), z: -Math.cos(yaw) }
      const right = { x: Math.cos(yaw), z: -Math.sin(yaw) }
      dx = right.x * axis.x + forward.x * (-axis.y)
      dz = right.z * axis.x + forward.z * (-axis.y)
    } else {
      dx = Math.sin(this.facing); dz = Math.cos(this.facing)
    }
    const len = Math.hypot(dx, dz) || 1
    this.dodgeDir.set(dx / len, 0, dz / len)
    this.stamina -= this.derived.dodgeCost
    this.dodgeTime = .28
    this.iFrames = .34
    this.outOfCombat = 0
    this.game.audio?.sfx('dodge')
    this.game.fx.burst(new THREE.Vector3(this.pos.x, this.pos.y + .5, this.pos.z), 0xd8e8ff, 12, { speed: 1.5, life: .4 })
  }

  startBlock() {
    if (this.dead) return
    this.blocking = true
    this.blockTime = 0
    this.parryReady = .22
  }

  stopBlock() {
    this.blocking = false
    this.parryReady = 0
  }

  skill1() {
    if (this.dead || this.cooldowns.skill1 > 0) return
    const cls = JURAMENTOS[this.save.className] || JURAMENTOS.filo
    const cost = 22
    if (this.mp < cost) { this.game.toast('Maná insuficiente.', '✦'); return }
    this.mp -= cost
    this.cooldowns.skill1 = 7.5
    this.skillData.cd1 = 7.5
    this.outOfCombat = 0
    this.game.audio?.sfx('magic')
    const dir = new THREE.Vector3(Math.sin(this.facing), 0, Math.cos(this.facing))
    if (cls.skill === 'bastion') {
      this.shield = Math.max(this.shield, 75)
      this.addEffect('bastion', 'Bastión', 5, { color: 0xffe0a8, reduction: .55 })
      this.game.fx.ring(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0xffe0a8, 4.4, { life: .8 })
      for (const e of this.game.world.enemies) {
        if (!e.alive) continue
        const d = Math.hypot(e.pos.x - this.pos.x, e.pos.z - this.pos.z)
        if (d < 5) e.knockback(this.pos, 6)
      }
      this.game.toast('Bastión del Alba: daño reducido y enemigos empujados.', '⬡')
    } else if (cls.skill === 'tajo') {
      const start = this.pos.clone()
      this.pos.addScaledVector(dir, 6.5)
      this.clampPosition()
      const path = new THREE.Vector3().subVectors(this.pos, start)
      this.game.fx.slash(this.pos, this.facing, 0xffb08a, 2.6)
      this.game.fx.burst(new THREE.Vector3(this.pos.x, this.pos.y + 1, this.pos.z), 0xffb08a, 26, { speed: 5 })
      for (const e of this.game.world.enemies) {
        if (!e.alive) continue
        const to = new THREE.Vector3(e.pos.x - start.x, 0, e.pos.z - start.z)
        if (to.length() < 3 + path.length() * .55) {
          const dot = to.clone().normalize().dot(dir)
          if (dot > -.35) e.takeDamage(Math.round(this.derived.attack * 1.7), { source: 'skill', dir: dir.clone(), crit: true })
        }
      }
      this.game.shakeCamera?.(-.2, .2)
    } else {
      const from = new THREE.Vector3(this.pos.x, this.pos.y + 1.25, this.pos.z)
      const to = from.clone().addScaledVector(dir, 22)
      this.game.fx.beam(from, to, 0x9cd8ff, .16)
      this.game.fx.burst(from, 0x9cd8ff, 20, { speed: 4 })
      for (const e of this.game.world.enemies) {
        if (!e.alive) continue
        const toE = new THREE.Vector3(e.pos.x - this.pos.x, 0, e.pos.z - this.pos.z)
        if (toE.length() > 22) continue
        if (toE.clone().normalize().dot(dir) > .93) {
          e.takeDamage(Math.round(this.derived.attack * 1.8 * this.derived.powerSkill), { source: 'skill', crit: true })
          e.slow(1.6, .5)
        }
      }
      this.mp = Math.min(this.derived.mp, this.mp + 8)
    }
    this.game.ui?.refreshHUD?.()
  }

  skill2() {
    if (this.dead || this.cooldowns.skill2 > 0) return
    if (this.mp < 30) { this.game.toast('Maná insuficiente.', '✦'); return }
    this.mp -= 30
    this.cooldowns.skill2 = 16
    this.skillData.cd2 = 16
    this.outOfCombat = 0
    const dmg = this.derived.attack * 1.35 * this.derived.powerSkill
    this.game.fx.ring(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0x9fc8ff, 6.2, { life: 1.1 })
    this.game.fx.burst(new THREE.Vector3(this.pos.x, this.pos.y + 1, this.pos.z), 0x9fc8ff, 34, { speed: 7, life: .9 })
    for (const e of this.game.world.enemies) {
      if (!e.alive) continue
      const d = Math.hypot(e.pos.x - this.pos.x, e.pos.z - this.pos.z)
      if (d < 7) {
        e.takeDamage(Math.round(dmg), { source: 'skill', crit: false })
        e.slow(3.2, .55)
      }
    }
    this.game.audio?.sfx('magic')
    this.game.toast('Don del Velo: onda de resonancia.', '✦')
  }

  useCreature() {
    if (this.dead || this.cooldowns.creature > 0) return
    const data = this.companionData
    if (!data) { this.game.toast('No hay una criatura invocada.', '❖'); return }
    const def = data.def
    this.cooldowns.creature = Math.max(8, def.cooldown - (data.level - 1) * .5)
    this.creatureCooldown = this.cooldowns.creature
    this.outOfCombat = 0
    this.game.audio?.sfx('capture')
    const pos = new THREE.Vector3(this.pos.x, this.pos.y + 1, this.pos.z)
    const enemies = this.game.world.enemies.filter(e => e.alive)
    switch (data.id) {
      case 'lumifin':
        this.heal(this.derived.hp * .32)
        this.addEffect('purify', 'Luz de Lumen', 5, { color: 0x9fe8ff })
        this.game.fx.ring(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0x9fe8ff, 3.2, { life: .8 })
        break
      case 'bramiel':
        this.shield = Math.max(this.shield, 45)
        this.addEffect('bark', 'Piel de Corteza', 8, { color: 0x8fd6a0, reduction: .2 })
        break
      case 'grimpola': {
        const targets = enemies.sort((a, b) => Math.hypot(a.pos.x - this.pos.x, a.pos.z - this.pos.z) - Math.hypot(b.pos.x - this.pos.x, b.pos.z - this.pos.z)).slice(0, 4)
        let last = pos.clone()
        for (const e of targets) {
          const to = new THREE.Vector3(e.pos.x, e.pos.y + 1, e.pos.z)
          this.game.fx.beam(last, to, 0x8ab9ff, .07)
          e.takeDamage(Math.round(20 + this.save.level * 3), { source: 'creature' })
          e.stun(1.1)
          last = to
        }
        break
      }
      case 'brasal':
        this.game.fx.ring(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0xff8a4c, 5.2, { life: .9 })
        for (const e of enemies) {
          if (Math.hypot(e.pos.x - this.pos.x, e.pos.z - this.pos.z) < 6) {
            e.takeDamage(Math.round(34 + this.save.level * 4), { source: 'creature' })
            e.burn(6, 5)
          }
        }
        break
      case 'umbrino': {
        const target = enemies.sort((a, b) => Math.hypot(a.pos.x - this.pos.x, a.pos.z - this.pos.z) - Math.hypot(b.pos.x - this.pos.x, b.pos.z - this.pos.z))[0]
        if (target) {
          const behind = new THREE.Vector3(target.pos.x - Math.sin(target.facing || 0) * 2.2, target.pos.y, target.pos.z - Math.cos(target.facing || 0) * 2.2)
          this.pos.copy(behind)
          this.facing = Math.atan2(target.pos.x - this.pos.x, target.pos.z - this.pos.z)
          this.game.fx.burst(pos, 0x8f7cc9, 20, { speed: 3 })
          target.takeDamage(Math.round((45 + this.save.level * 5) * 1.6), { source: 'creature', crit: true })
        }
        break
      }
      case 'cineronte':
        this.addEffect('taunt', 'La Montaña Recuerda', 7, { color: 0xc2a98a, reduction: .35 })
        for (const e of enemies) if (Math.hypot(e.pos.x - this.pos.x, e.pos.z - this.pos.z) < 9) e.taunt(this, 7)
        break
      case 'petreluz':
        for (const e of enemies) if (Math.hypot(e.pos.x - this.pos.x, e.pos.z - this.pos.z) < 12) e.slow(5, .55)
        this.game.fx.ring(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0xa6e5ff, 9, { life: 1.2 })
        break
      case 'celemn': {
        const from = new THREE.Vector3(this.pos.x, this.pos.y + 1.4, this.pos.z)
        const to = from.clone().addScaledVector(new THREE.Vector3(Math.sin(this.facing), .1, Math.cos(this.facing)), 26)
        this.game.fx.beam(from, to, 0xffe0a0, .28)
        for (const e of enemies) {
          const d = Math.hypot(e.pos.x - this.pos.x, e.pos.z - this.pos.z)
          if (d < 15) { e.takeDamage(Math.round(80 + this.save.level * 6), { source: 'creature', crit: true }); e.stun(1.4) }
        }
        break
      }
      default: break
    }
    this.game.toast(`${def.name}: ${def.ability}`, '❖')
    this.game.ui?.refreshHUD?.()
  }

  potion() {
    if (this.dead) return
    if (!this.game.usePotion()) this.game.toast('No tienes pociones.', '⚠')
  }

  capture() {
    if (this.dead) return
    this.game.tryCapture(this.captureTarget)
  }

  heal(amount) {
    const before = this.hp
    this.hp = Math.min(this.derived.hp, this.hp + amount)
    const healed = Math.round(this.hp - before)
    if (healed > 0) {
      this.game.fx.burst(new THREE.Vector3(this.pos.x, this.pos.y + 1.2, this.pos.z), 0x9fe7a2, 14, { speed: 1.8, gravity: 1.2 })
      this.game.ui?.damageAt?.(...this.game.projectPoint(new THREE.Vector3(this.pos.x, this.pos.y + 2, this.pos.z)), `+${healed}`, 'heal')
    }
    return healed
  }

  restoreMana(amount) {
    this.mp = Math.min(this.derived.mp, this.mp + amount)
  }

  addEffect(id, label, duration, opts = {}) {
    const existing = this.effects.find(e => e.id === id)
    if (existing) { existing.time = Math.max(existing.time, duration); return }
    this.effects.push({ id, label, time: duration, duration, ...opts })
  }

  effectiveReduction() {
    let r = this.derived.reduction
    for (const e of this.effects) if (e.reduction) r = 1 - (1 - r) * (1 - e.reduction)
    return Math.min(.9, r)
  }

  takeDamage(amount, opts = {}) {
    if (this.dead) return
    if (this.iFrames > 0 || this.dodgeTime > 0) {
      if (opts.source?.def) this.game.ui?.damageAt?.(...this.game.projectPoint(new THREE.Vector3(this.pos.x, this.pos.y + 2, this.pos.z)), 'ESQUIVA', 'capture')
      return
    }
    this.outOfCombat = 0
    let dmg = amount * (this.game.difficulty?.taken ?? 1)
    let parried = false
    if (this.blocking) {
      const attacker = opts.source
      if (this.parryReady > 0 && attacker?.stun && Math.hypot(attacker.pos.x - this.pos.x, attacker.pos.z - this.pos.z) < 4.5) {
        parried = true
        attacker.stun(2.4)
        this.stamina = Math.min(this.derived.stamina, this.stamina + 25)
        this.game.audio?.sfx('parry')
        this.game.toast('¡Paro perfecto!', '◈')
        this.game.fx.ring(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0xffffff, 2.8, { life: .4 })
      } else {
        const cost = this.derived.blockCost * (opts.heavy ? 2 : 1)
        if (this.stamina <= 0) {
          this.game.toast('¡Guardia rota!', '⚠')
        } else {
          dmg *= .24
          this.stamina = Math.max(0, this.stamina - cost)
        }
      }
    }
    if (!parried) {
      dmg *= 1 - this.effectiveReduction()
      if (this.shield > 0) {
        const absorbed = Math.min(this.shield, dmg)
        this.shield -= absorbed
        dmg -= absorbed
        this.game.fx.burst(new THREE.Vector3(this.pos.x, this.pos.y + 1.2, this.pos.z), 0x9fe8ff, 10, { speed: 2 })
      }
      dmg = Math.max(1, Math.round(dmg))
      this.hp -= dmg
      this.hurtFlash = .12
      this.mesh.userData.lastFlash = true
      this.applyHurtFlash()
      this.game.audio?.sfx('hit')
      this.game.ui?.flash?.('rgba(255,70,50,.16)')
      this.game.shakeCamera?.(.25, .2)
      this.game.hitStop = Math.max(this.game.hitStop, .04)
      const p = this.game.projectPoint(new THREE.Vector3(this.pos.x, this.pos.y + 1.9, this.pos.z))
      this.game.ui?.damageAt?.(p.x, p.y, `−${dmg}`, 'player')
    }
    this.game.ui?.refreshHUD?.()
    if (this.hp <= 0) this.die()
  }

  applyHurtFlash() {
    this.mesh.traverse(o => {
      if (o.material?.emissive) {
        if (o.material.userData.baseEmissive === undefined) o.material.userData.baseEmissive = o.material.emissive.getHex()
        o.material.emissive.setHex(0x7a1e16)
      }
    })
  }

  die() {
    if (this.dead) return
    this.dead = true
    this.hp = 0
    this.blocking = false
    this.game.audio?.sfx('death')
    this.game.fx.burst(new THREE.Vector3(this.pos.x, this.pos.y + 1, this.pos.z), 0xffe0a8, 30, { speed: 3.5, life: 1.2 })
    this.game.onPlayerDeath()
  }

  screenPos() {
    return this.game.projectPoint(new THREE.Vector3(this.pos.x, this.pos.y + 2.1, this.pos.z))
  }
}

import * as THREE from 'three'
import { ENEMIES } from '../data/enemies.js'
import { createEnemyModel } from '../world/models.js'
import { clamp, dampAngle, rand, TAU } from '../utils/math.js'

export class Enemy {
  constructor(game, defId, x, z, opts = {}) {
    this.game = game
    this.defId = defId
    this.def = ENEMIES[defId]
    if (!this.def) throw new Error(`Enemigo desconocido: ${defId}`)
    this.level = opts.level || 1
    const scale = 1 + Math.max(0, this.level - 1) * .08
    this.maxHp = Math.round(this.def.hp * (this.def.boss ? 1 : scale))
    this.hp = this.maxHp
    this.damage = this.def.damage * (this.def.boss ? 1 : 1 + Math.max(0, this.level - 1) * .05)
    this.alive = true
    this.boss = !!this.def.boss
    this.facing = Math.random() * TAU
    this.home = new THREE.Vector3(x, 0, z)
    this.pos = new THREE.Vector3(x, 0, z)
    this.state = 'idle'
    this.wanderTime = rand(1, 4)
    this.wanderDir = new THREE.Vector3()
    this.attackWindup = 0
    this.attackTimer = 0
    this.cooldown = rand(.8, 1.8)
    this.stagger = 0
    this.stunTime = 0
    this.slowTime = 0
    this.slowFactor = 1
    this.burnTime = 0
    this.burnDps = 0
    this.tauntTime = 0
    this.aggroTime = 0
    this.phase = 0
    this.phaseCount = this.boss ? 3 : 1
    this.specialTimer = 6
    this.invuln = 0
    this.deathTimer = 0
    this.bossDefeated = false
    this.orbit = Math.random() * TAU
    this.mesh = createEnemyModel(this.def)
    const ground = game.world?.zone?.heightAt(x, z) ?? 0
    this.pos.y = ground
    this.mesh.position.copy(this.pos)
    this.mesh.rotation.y = this.facing
    game.scene?.add(this.mesh)
    this.light = null
    if (this.boss) {
      this.light = new THREE.PointLight(this.def.accent, 1.4, 12)
      this.light.position.y = 2
      this.mesh.add(this.light)
    }
  }

  get radius() { return this.def.radius || .7 }

  update(dt) {
    if (!this.alive) {
      this.deathTimer += dt
      if (this.deathTimer > .2) {
        this.mesh.position.y -= dt * .6
        this.mesh.rotation.z += dt * .5
        this.mesh.traverse(o => { if (o.material?.opacity !== undefined && o.material.transparent) o.material.opacity = Math.max(0, o.material.opacity - dt * .6) })
      }
      if (this.deathTimer > 2.2) this.remove()
      return
    }
    if (this.game.state !== 'playing') return
    dt = Math.min(dt, .05)
    if (this.invuln > 0) this.invuln -= dt
    if (this.stunTime > 0) {
      this.stunTime -= dt
      this.animate(dt, true)
      return
    }
    if (this.slowTime > 0) { this.slowTime -= dt; if (this.slowTime <= 0) this.slowFactor = 1 }
    if (this.tauntTime > 0) this.tauntTime -= dt
    if (this.burnTime > 0) {
      this.burnTime -= dt
      this.burnTick = (this.burnTick || 0) + dt
      if (this.burnTick > .55) {
        this.burnTick = 0
        this.takeDamage(this.burnDps, { source: 'burn', silent: true })
        if (!this.alive) return
      }
    }

    const player = this.game.player
    if (!player || player.dead) { this.animate(dt, true); return }
    const dx = player.pos.x - this.pos.x, dz = player.pos.z - this.pos.z
    const dist = Math.hypot(dx, dz)
    if (dist < this.def.aggro && this.state === 'idle') {
      this.state = 'chase'
      if (this.boss) this.game.onBossAggro?.(this)
    }
    if (dist > this.def.aggro * 1.9 && !this.boss) {
      this.aggroTime += dt
      if (this.aggroTime > 6) { this.state = 'return'; this.aggroTime = 0 }
    } else this.aggroTime = 0

    if (this.def.boss) this.updatePhase(dist)

    if (this.cooldown > 0) this.cooldown -= dt
    if (this.specialTimer > 0) this.specialTimer -= dt

    if (this.state === 'return') {
      const hd = Math.hypot(this.home.x - this.pos.x, this.home.z - this.pos.z)
      if (hd < 1.5) { this.state = 'idle'; this.hp = Math.min(this.maxHp, this.hp + this.maxHp * .4) }
      else this.moveToward(this.home.x, this.home.z, this.def.speed * dt, dt)
      this.animate(dt)
      return
    }

    if (this.attackWindup > 0) {
      this.attackWindup -= dt
      this.facing = dampAngle(this.facing, Math.atan2(dx, dz), 6, dt)
      this.mesh.rotation.y = this.facing
      if (this.attackWindup <= 0) this.executeAttack(dist)
      this.animate(dt, false, true)
      return
    }

    if (this.state === 'idle') {
      this.wanderTime -= dt
      if (this.wanderTime <= 0) {
        this.wanderTime = rand(2.5, 6)
        const a = Math.random() * TAU, r = rand(1, 5)
        this.wanderTarget = { x: this.home.x + Math.cos(a) * r, z: this.home.z + Math.sin(a) * r }
      }
      if (this.wanderTarget) {
        const wd = Math.hypot(this.wanderTarget.x - this.pos.x, this.wanderTarget.z - this.pos.z)
        if (wd > .4) this.moveToward(this.wanderTarget.x, this.wanderTarget.z, this.def.speed * .32 * dt, dt)
        else this.wanderTarget = null
      }
      this.animate(dt, true)
      return
    }

    // Persecución
    this.facing = dampAngle(this.facing, Math.atan2(dx, dz), this.boss ? 4.2 : 7, dt)
    this.mesh.rotation.y = this.facing
    if (this.boss && this.specialTimer <= 0 && dist < 18) {
      this.useSpecial(dist)
      return
    }
    const range = this.def.attackRange
    if (dist > range) {
      const speed = this.def.speed * (this.boss ? 1 + this.phase * .1 : 1) * (this.slowFactor || 1)
      this.moveToward(player.pos.x, player.pos.z, speed * dt, dt)
    } else if (this.cooldown <= 0) {
      this.beginAttack()
    }
    this.animate(dt)
  }

  updatePhase(dist) {
    const pct = this.hp / this.maxHp
    const wanted = pct < .33 ? 2 : pct < .66 ? 1 : 0
    if (wanted > this.phase) {
      this.phase = wanted
      this.damage *= 1.12
      this.specialTimer = 1.6
      this.invuln = .5
      const pos = new THREE.Vector3(this.pos.x, this.pos.y + 1, this.pos.z)
      this.game.fx.ring(pos, this.def.accent, 6 + this.phase * 2, { life: 1 })
      this.game.fx.burst(pos, this.def.accent, 30, { speed: 5 })
      this.game.shakeCamera?.(.3, .35)
      this.game.audio?.sfx('boss')
      this.game.toast(`${this.def.name} cambia de fase.`, '⚠')
      this.game.ui?.updateBoss?.(pct, this.phase)
    }
  }

  beginAttack() {
    this.attackWindup = this.boss ? .72 : .46
    this.cooldown = (this.def.cooldown || 2) * (this.boss ? .9 : 1) * rand(.88, 1.12) / (1 + this.phase * .18)
    this.attackTimer = this.attackWindup
    this.game.audio?.sfx('swing')
    const pos = new THREE.Vector3(this.pos.x, this.pos.y + .12, this.pos.z)
    this.game.fx.ring(pos, this.def.boss ? 0xff6a4a : 0xffb28a, this.def.attackRange * .8, { life: this.attackWindup, opacity: .5 })
  }

  executeAttack(dist) {
    const player = this.game.player
    this.attackTimer = 0
    if (!player || player.dead) return
    this.game.audio?.sfx(this.def.boss ? 'heavy' : 'swing')
    if (this.def.ranged) {
      this.fireProjectile(player, this.def.boss ? 1.2 : 1)
      if (this.def.boss) this.fireFan(player, 3, .28)
    } else if (dist < this.def.attackRange + .9) {
      player.takeDamage(this.damage, { source: this, heavy: this.def.boss })
      this.game.fx.slash(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), this.facing, this.def.accent, this.boss ? 2.5 : 1.4)
    }
    if (this.boss) {
      const pos = new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z)
      this.game.fx.ring(pos, this.def.accent, this.def.attackRange + 2.5, { life: .6 })
    }
  }

  fireProjectile(player, spread = 0) {
    const from = new THREE.Vector3(this.pos.x, this.pos.y + 1.25, this.pos.z)
    const target = new THREE.Vector3(player.pos.x, player.pos.y + 1.1, player.pos.z)
    const dir = target.sub(from).normalize()
    if (spread) { dir.x += rand(-spread, spread); dir.z += rand(-spread, spread); dir.normalize() }
    this.game.fx.projectile({
      pos: from, dir, speed: this.def.boss ? 13 : 11, damage: this.damage,
      color: this.def.accent, owner: 'enemy', radius: .22, life: 4
    })
  }

  fireFan(player, count = 5, spread = .42) {
    const from = new THREE.Vector3(this.pos.x, this.pos.y + 1.3, this.pos.z)
    const target = new THREE.Vector3(player.pos.x, player.pos.y + 1, player.pos.z)
    const base = target.sub(from).normalize()
    for (let i = 0; i < count; i++) {
      const a = (i - (count - 1) / 2) * spread
      const dir = base.clone().applyAxisAngle(new THREE.Vector3(0, 1, 0), a)
      this.game.fx.projectile({
        pos: from.clone(), dir, speed: 10, damage: this.damage * .8,
        color: this.def.accent, owner: 'enemy', radius: .24, life: 4.5
      })
    }
  }

  useSpecial(dist) {
    this.specialTimer = this.boss ? rand(7.5, 11) : 10
    const player = this.game.player
    if (!player) return
    if (this.def.model === 'colossus') {
      this.slamAttack(player, 7.5)
    } else if (this.def.model === 'lord') {
      this.fireFan(player, 5, .5)
      this.game.fx.ring(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0xff6a32, 4, { life: .8 })
      this.game.toast('Varok invoca la Corona de Brasas.', '⚠')
    } else if (this.def.model === 'convergence') {
      this.fireFan(player, 9, .32)
      this.slamAttack(player, 6.5, 1.2)
      this.game.toast('La Convergencia repite todos tus ataques.', '⚠')
    } else if (this.def.model === 'seraph') {
      this.slamAttack(player, 6)
      this.healSelf(this.maxHp * .03)
    } else {
      this.fireFan(player, 5, .45)
    }
  }

  slamAttack(player, radius = 6, delay = 1.05) {
    const target = new THREE.Vector3(player.pos.x, player.pos.y, player.pos.z)
    const ring = this.game.fx.ring(target, 0xff5a3c, radius, { life: delay, opacity: .8 })
    ring.material.opacity = .25
    setTimeout(() => {
      if (!this.alive || this.game.state === 'destroyed') return
      this.game.fx.ring(target, 0xff7a45, radius * 1.15, { life: .7 })
      this.game.fx.burst(new THREE.Vector3(target.x, target.y + .5, target.z), 0xff7a45, 30, { speed: 6 })
      this.game.shakeCamera?.(.45, .4)
      this.game.audio?.sfx('heavy')
      if (this.game.player && Math.hypot(this.game.player.pos.x - target.x, this.game.player.pos.z - target.z) < radius) {
        this.game.player.takeDamage(this.damage * 1.35, { source: this, heavy: true })
      }
      for (const e of this.game.world?.enemies || []) {
        if (e !== this && e.alive && Math.hypot(e.pos.x - target.x, e.pos.z - target.z) < radius) e.takeDamage(this.damage * .3, { silent: true })
      }
    }, delay * 1000)
  }

  moveToward(x, z, step, dt) {
    const dx = x - this.pos.x, dz = z - this.pos.z
    const d = Math.hypot(dx, dz) || 1
    const nx = this.pos.x + dx / d * step
    const nz = this.pos.z + dz / d * step
    const resolved = this.game.world?.resolveCollision?.(nx, nz, this.radius) || { x: nx, z: nz }
    this.pos.x = resolved.x
    this.pos.z = resolved.z
    const zone = this.game.world?.zone
    if (zone) this.pos.y = zone.heightAt(this.pos.x, this.pos.z)
    this.mesh.position.copy(this.pos)
    this.animate(dt)
  }

  healSelf(amount) {
    this.hp = Math.min(this.maxHp, this.hp + amount)
    this.game.fx.burst(new THREE.Vector3(this.pos.x, this.pos.y + 1.5, this.pos.z), 0x9fe7a2, 14, { speed: 2, gravity: 1 })
  }

  takeDamage(amount, opts = {}) {
    if (!this.alive || this.invuln > 0) return
    if (this.game.flags?.[`invuln_${this.defId}`]) return
    const dmg = Math.max(1, Math.round(amount))
    this.hp -= dmg
    this.state = 'chase'
    this.aggroTime = 0
    if (opts.dir) {
      const kb = opts.combo === 2 ? .35 : .15
      this.pos.x += opts.dir.x * kb
      this.pos.z += opts.dir.z * kb
      this.mesh.position.copy(this.pos)
    }
    if (!opts.silent) {
      this.game.ui?.setTarget?.(this)
      const p = this.game.projectPoint(new THREE.Vector3(this.pos.x, this.pos.y + (this.boss ? 3.2 : 1.8), this.pos.z))
      this.game.ui?.damageAt?.(p.x, p.y, `${dmg}`, opts.crit ? 'crit' : '')
      this.game.audio?.sfx(opts.crit ? 'crit' : 'hit')
      this.game.fx.burst(new THREE.Vector3(this.pos.x, this.pos.y + 1, this.pos.z), opts.crit ? 0xffd05e : this.def.accent, opts.crit ? 16 : 9, { speed: 2.6, life: .45 })
      this.stagger += opts.combo === 2 ? 14 : 6
      if (this.stagger > (this.boss ? 90 : 38)) {
        this.stagger = 0
        this.stun(this.boss ? .7 : 1.3)
        this.game.toast(`${this.def.name} está aturdido.`, '✦')
      }
    }
    if (this.boss) {
      this.game.ui?.updateBoss?.(this.hp / this.maxHp, this.phase)
      this.game.onBossHit?.(this)
    }
    if (this.hp <= 0) this.die()
  }

  stun(seconds) {
    if (!this.alive) return
    this.stunTime = Math.max(this.stunTime, this.boss ? seconds * .65 : seconds)
    this.attackWindup = 0
    this.game.fx.burst(new THREE.Vector3(this.pos.x, this.pos.y + 1.6, this.pos.z), 0xffe6a0, 14, { speed: 2 })
  }

  slow(seconds, factor = .5) {
    this.slowTime = Math.max(this.slowTime, seconds)
    this.slowFactor = Math.min(this.slowFactor, factor)
  }

  burn(seconds, dps) {
    this.burnTime = Math.max(this.burnTime, seconds)
    this.burnDps = Math.max(this.burnDps, dps)
  }

  taunt(player, seconds) {
    this.state = 'chase'
    this.tauntTime = seconds
    this.aggroTime = 0
  }

  knockback(from, force) {
    const dx = this.pos.x - from.x, dz = this.pos.z - from.z
    const d = Math.hypot(dx, dz) || 1
    this.pos.x += dx / d * force * (this.boss ? .2 : 1)
    this.pos.z += dz / d * force * (this.boss ? .2 : 1)
    this.mesh.position.copy(this.pos)
    this.stun(this.boss ? .25 : .6)
  }

  die() {
    if (!this.alive) return
    this.alive = false
    this.hp = 0
    this.state = 'dead'
    this.deathTimer = 0
    const p = new THREE.Vector3(this.pos.x, this.pos.y + 1, this.pos.z)
    this.game.fx.burst(p, this.def.accent, this.boss ? 60 : 24, { speed: this.boss ? 7 : 3.4, life: this.boss ? 1.6 : .9 })
    this.game.fx.ring(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), this.def.accent, this.boss ? 8 : 2.4, { life: .8 })
    this.game.audio?.sfx(this.boss ? 'levelup' : 'hit')
    if (this.boss) {
      this.game.shakeCamera?.(.5, .8)
      this.game.ui?.hideBoss?.()
      this.game.fx.ring(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0xffe6a8, 14, { life: 1.6 })
    }
    this.game.onEnemyDeath(this)
  }

  remove() {
    this.deadRemoved = true
    if (this.mesh.parent) this.mesh.parent.remove(this.mesh)
    this.mesh.traverse(o => { o.geometry?.dispose?.(); if (o.material && !Array.isArray(o.material)) o.material.dispose() })
  }

  animate(dt, stunned = false, windup = false) {
    const rig = this.mesh.userData.rig
    if (!rig) return
    const t = performance.now() * .001 + this.orbit
    const speed = this.state === 'chase' && !stunned ? this.def.speed : 1
    this.orbit += dt * (this.state === 'chase' ? .3 : .1)
    if (rig.body) {
      rig.body.position.y = (rig.baseY || 0) + Math.sin(t * 2.2) * .035
      if (this.boss) rig.body.position.y += Math.sin(t * 1.3) * .03
      rig.body.rotation.z = stunned ? Math.sin(t * 8) * .06 : 0
    }
    if (rig.legL && rig.legR) {
      const sw = Math.sin(t * 6 * Math.min(1.4, speed / 3)) * (this.state === 'chase' ? .5 : .18)
      rig.legL.rotation.x = sw
      rig.legR.rotation.x = -sw
    }
    if (rig.legs) rig.legs.forEach((l, i) => { l.rotation.x = Math.sin(t * 7 + (i % 2) * Math.PI) * .45 })
    if (rig.armL && rig.armR && rig.armR !== rig.weapon) {
      const sw = Math.sin(t * 5) * .18
      rig.armL.rotation.x = sw
      rig.armR.rotation.x = -sw
      if (windup) {
        rig.armR.rotation.x = -2.2
        rig.armR.rotation.z = -.5
      }
    }
    if (rig.armR && this.attackTimer > .1 && !windup) {
      rig.armR.rotation.x = -1.3 + Math.sin(t * 18) * .2
    }
    if (rig.head) {
      rig.head.rotation.y = Math.sin(t * .8) * .06
      if (this.boss) rig.head.rotation.x = Math.sin(t * .5) * .04
    }
    if (rig.wings) rig.wings.forEach((w, i) => { w.rotation.z = Math.sin(t * 3 + i) * .2 })
    if (rig.rings) {
      rig.body.children?.forEach(o => { if (o.userData.spin) { o.rotation.z += dt * o.userData.spin; o.rotation.y += dt * o.userData.spin * .4 } })
    }
    if (rig.shards) {
      rig.shards.children.forEach((s, i) => {
        s.rotation.y += dt; s.rotation.x += dt * .7
        s.position.y += Math.sin(t * 1.8 + i) * dt * .25
      })
    }
    const bodyChildren = rig.body?.children || []
    for (const o of bodyChildren) {
      if (o.userData.phase !== undefined) o.rotation.z = Math.sin(t * 2.4 + o.userData.phase) * .12
    }
    // Telegráfico
    if (windup) {
      const k = 1 + Math.sin(performance.now() * .03) * .04
      this.mesh.scale.setScalar((this.def.scale || 1) * k)
      if (this.light) this.light.intensity = 2.4
    } else {
      this.mesh.scale.setScalar(this.def.scale || 1)
      if (this.light) this.light.intensity = 1.2
    }
  }
}

