209: // ───────────────────────────── MERA ─────────────────────────────
210: function mera(g) {
211:   if (!g.quests.isActive('flores_altar') && !done(g, 'flores_altar')) {
212:     return N('Cada amanecer enciendo cinco velas por los que no volvieron. Este año no tengo flores de lumen. Crecen cerca del agua y brillan cuando nadie las mira. ¿Me traerías cinco? El altar no exige mucho, pero tampoco olvida.', {
213:       speaker: 'Mera', role: 'Guardiana del altar',
214:       choices: [
215:         C('Traeré las flores.', 'close', () => { g.quests.start('flores_altar'); }),
216:         C('Ahora no puedo.', 'close')
217:       ]
218:     })
219:   }
220:   if (has(g, 'flores_altar')) {
221:     const n = g.inventoryCount('flor_lumen')
222:     return N(n < 5 ? `Llevas ${n} de cinco. Las flores de lumen se esconden entre la hierba alta, cerca del río y del bosque. No las arranques con raíz: mañana querrán volver.` : 'Cinco flores. Huelen a lluvia y a principio. Espera… *las coloca en el altar* El nombre de los caídos se ha vuelto a oír. Gracias, viajero. Toma esto: perteneció a alguien que también volvió.', {
223:       speaker: 'Mera', role: 'Guardiana del altar', next: 'close'
224:     })
225:   }
226:   return N('El altar está completo otra vez. Si alguna vez el Velo te enseña algo que no quieres ver, vuelve aquí. La luz de las velas no juzga; solo acompaña.', {
227:     speaker: 'Mera', role: 'Guardiana del altar', next: 'close'
228:   })
229: }
