264: // ───────────────────────────── KAELEN ─────────────────────────────
265: function kaelen(g) {
266:   if (has(g, 'tierras_ceniza')) {
267:     return N('Así que la Puerta de Ceniza sigue aceptando visitantes. Pensé que ya no quedaba nadie al otro lado. Soy Kaelen. Este campamento es lo que queda de Drakmor que no se ha arrodillado ante el Señor de Ceniza.', {
268:       speaker: 'Kaelen', role: 'Último rebelde',
269:       choices: [
270:         C('¿Quién es Varok?', N('Un padre. Un rey. Un hombre que perdió a su hija y decidió declararle la guerra al tiempo. Su dolor se filtró en la tierra y ahora respira por ella. Los ceniceros que ves fuera no son monstruos: son soldados que olvidaron por qué luchaban.', {
271:           speaker: 'Kaelen', role: 'Último rebelde',
272:           choices: [C('¿Qué quieres de mí?', N('La Fortaleza de Varok tiene una puerta que solo se abre desde dentro. Tengo la llave, pero no la fuerza. Tú tienes la fuerza, pero no la llave. Y hay algo más: tres memorias de su hija están esparcidas por el bosque y el santuario. Si las reúnes, quizá puedas hablarle antes de que te mate.', {
273:             speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
274:           }))]
275:         })),
276:         C('He venido a detener la Ruptura.', N('Todos venimos a detener algo. Varok quiere detener la muerte. Yo quiero detener a Varok. Tú querrás detener el Velo. Ninguno lo conseguirá solo. Por eso estamos aquí, alrededor de una hoguera que ya no calienta.', {
277:           speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
278:         }))
279:       ]
280:     })
281:   }
282:   if (just(g, 'tierras_ceniza')) {
283:     return N('Toma la Llave de Ceniza. Abre la puerta de la fortaleza, pero antes busca las tres Memorias de Ceniza: una en el bosque de obsidiana, otra en sus profundidades y una más en el santuario del este. Son recuerdos de la hija de Varok. Si aún queda un padre dentro de él, esas memorias lo encontrarán.', {
284:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
285:     })
286:   }
287:   if (has(g, 'hija_ceniza')) {
288:     return N(`${g.quests.stepProgress('hija_ceniza', 0)} de tres memorias. La del santuario está junto a la lava; la del bosque, donde los árboles tienen más sed. Cuando las tengas, vuelve. No quiero que entres en la fortaleza con las manos vacías.`, {
289:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
290:     })
291:   }
292:   if (just(g, 'hija_ceniza')) {
293:     return N('Conozco esa mirada. Has visto a la niña. Se llamaba Sela. Varok construyó un reino entero para no tener que decir su nombre en pasado. Ahora entra y dile que el tiempo no se detiene: se comparte. Aunque tenga que ser con una espada en la mano.', {
294:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
295:     })
296:   }
297:   if (has(g, 'senor_ceniza')) {
298:     return N('La brecha está abierta. La puerta de la fortaleza te espera al norte, más allá de la grieta. Yo cubriré tu retirada desde aquí. Y forastero… si puedes, no lo mates. Si no puedes, no dejes que su muerte sea en vano.', {
299:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
300:     })
301:   }
302:   if (!g.quests.isActive('faro_ceniza') && !done(g, 'faro_ceniza') && (g.flags.varok_defeated || done(g, 'senor_ceniza'))) {
303:     return N('La fortaleza está en silencio. Pero el faro del sureste sigue apagado, y hay gente perdida en la grieta. Enciéndelo. No te costará nada, y a alguien le costará todo.', {
304:       speaker: 'Kaelen', role: 'Último rebelde',
305:       choices: [
306:         C('Voy a encenderlo.', 'close', () => { g.quests.start('faro_ceniza'); }),
307:         C('Ahora no.', 'close')
308:       ]
309:     })
310:   }
311:   if (done(g, 'senor_ceniza')) {
312:     return N(g.flags.varok_spared
313:       ? 'Le perdonaste. No sé si fue misericordia o crueldad, pero fue tuyo. Varok bajó la espada y por primera vez en años el fuego de la fortaleza no olía a carne.'
314:       : 'Le quitaste todo. Su fuego, su memoria, su nombre. Drakmor está a salvo, pero esta tierra ya no recordará que un padre intentó salvar a su hija. Eso también es una muerte.', {
315:       speaker: 'Kaelen', role: 'Último rebelde',
316:       choices: [
317:         C('¿Qué será de Drakmor?', N('Será lo que hagamos con la ceniza. No con la que cae del cielo: con la que llevamos dentro. La Puerta del Cielo está abierta, al sureste de la fortaleza. Kansordore te espera. Ojalá encuentres allí una respuesta menos dolorosa que la nuestra.', {
318:           speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
319:         })),
320:         C('Cuida de los tuyos.', 'close')
321:       ]
322:     })
323:   }
324:   return N('La ceniza cae más despacio cuando alguien la mira. Quédate junto al fuego si lo necesitas. Mañana el mundo seguirá roto, pero tú estarás un poco menos.', {
325:     speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
326:   })
327: }
