112:   if (has(g, 'don_resonancia')) {
113:     const step = g.quests.stepIndex('don_resonancia')
114:     if (step <= 0) {
115:       return N('No mates a la criatura. Ya sé que la espada te lo pide. Las espadas siempre piden lo fácil. Déjala débil, pero viva, y ofrecele tu mano. Si acepta, la luz de tu pecho cambiará de color un instante.', {
116:         speaker: 'Nara', role: 'Cazadora de ecos',
117:         choices: [
118:           C('¿Cómo sé cuándo está débil?', N('Cuando su nombre brille en tu mente. Cuando la barra de vida esté por debajo de un tercio, pulsa el vínculo. Si falla, no insistas como un ladrón: espera, vuelve a intentarlo. La confianza también tiene enfriamiento.', {
119:             speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
120:           })),
121:           C('¿Y si no quiere venir?', N('Entonces no viene. Un vínculo forzado es una jaula con otro nombre. Pero no te preocupes: casi todas las criaturas están cansadas de estar solas. Como nosotros.', {
122:             speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
123:           }))
124:         ]
125:       })
126:     }
127:     if (step === 1) {
128:       return N('Ve a por una. Las Lumifín duermen bajo los sauces, al este del claro. No corras hacia ellas: camina. Y cuando la captures, vuelve. Quiero ver la cara que pones.', {
129:         speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
130:       })
131:     }
132:   }
133:   if (just(g, 'don_resonancia') || (done(g, 'don_resonancia') && !g.flags.nara_bond)) {
134:     g.flags.nara_bond = true
135:     return N('No has domesticado una criatura. Has aceptado que otra vida importe más que tu prisa. Eso, forastero, es la primera lección de la Resonancia. La segunda la aprenderás cuando tengas que despedirte de ella.', {
136:       speaker: 'Nara', role: 'Cazadora de ecos',
137:       choices: [
138:         C('¿Las criaturas mueren?', N('Todo muere. Pero un vínculo deja un eco, y los ecos encuentran el camino de vuelta. Por eso el Velo tiene miedo de nosotros: no puede borrar lo que se comparte.', {
139:           speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
140:         })),
141:         C('Gracias, Nara.', 'close')
142:       ]
143:     })
144:   }
145:   if (!g.quests.isActive('cazador_ecos') && !done(g, 'cazador_ecos') && (done(g, 'don_resonancia') || g.flags.nara_bond)) {
146:     return N('Tengo un encargo para ti, si te atreves. Tres criaturas distintas, tres vínculos. No por coleccionar: por demostrar que puedes escuchar más de una canción sin desafinar.', {
147:       speaker: 'Nara', role: 'Cazadora de ecos',
148:       choices: [
149:         C('Acepto el desafío.', 'close', () => { g.quests.start('cazador_ecos'); }),
150:         C('Más adelante.', 'close')
151:       ]
152:     })
153:   }
154:   if (has(g, 'cazador_ecos')) {
155:     const n = g.quests.stepProgress('cazador_ecos', 0)
156:     return N(`${n >= 3 ? 'Tres canciones distintas. Lo sabía.' : `${n} de tres. Sigue escuchando.`} Las criaturas no son armas. Son testigos de lo que el Velo intenta borrar. Cuídalas y ellas te cuidarán cuando la espada no baste.`, {
157:       speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
158:     })
159:   }
160:   return N('El bosque está inquieto. Las Lumifín cantan en frecuencias que los humanos no oímos, pero tú no eres del todo humano, ¿verdad? Si alguna vez quieres saber qué eres, pregúntale a las criaturas. Ellas recuerdan más de lo que admiten.', {
161:     speaker: 'Nara', role: 'Cazadora de ecos',
162:     choices: [
163:       C('¿Conoces la Profecía de Jugador Cero?', N('Mi abuela la recitaba como una canción de cuna. «El que no tiene nombre elegirá el final; el que tiene nombre lo vivirá». Nunca supe si era una promesa o una advertencia.', {
164:         speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
165:       })),
166:       C('Adiós.', 'close')
167:     ]
168:   })
169: }
170: 
171: // ───────────────────────────── TOVIN ─────────────────────────────
172: function tovin(g) {
173:   if (!g.quests.isActive('espada_rota') && !done(g, 'espada_rota')) {
174:     return N('¡Tú! El de la espada que no debería existir. Esa hoja tiene más años que Valdoria y menos filo que una cuchara. Tráeme tres fragmentos de Hierro Estelar y te forjaré algo que no dé vergüenza. Las vetas brillan junto a las rocas viejas.', {
175:       speaker: 'Tovin', role: 'Herrero de Alda',
176:       choices: [
177:         C('Acepto. Necesito un filo mejor.', 'close', () => { g.quests.start('espada_rota'); }),
178:         C('¿No puedes usar hierro normal?', N('Puedo. Y también puedo coser una herida con hilo de pescar. El hierro estelar canta cuando lo golpeas. Lo normal solo grita.', {
179:           speaker: 'Tovin', role: 'Herrero de Alda',
180:           choices: [C('Buscaré tres fragmentos.', 'close', () => { g.quests.start('espada_rota'); })]
181:         })),
182:         C('Ahora no.', 'close')
183:       ]
184:     })
185:   }
186:   if (has(g, 'espada_rota')) {
187:     const n = g.inventoryCount('hierro_estelar')
188:     if (n < 3) return N(`Te faltan ${3 - n} fragmentos de Hierro Estelar. Mira cerca de las rocas antiguas, en las ruinas y en los cofres. Y no los vendas. Lo digo por experiencia.`, { speaker: 'Tovin', role: 'Herrero de Alda', next: 'close' })
189:     return N('Tres fragmentos. Pesan más de lo que parecen, ¿eh? Dame un momento. *golpea el yunque siete veces* No es superstición: son los siete nombres de la Gema. Ya está. Esto es una espada, no una reliquia oxidada.', {
190:       speaker: 'Tovin', role: 'Herrero de Alda', next: 'close'
191:     })
192:   }
193:   if (done(g, 'espada_rota')) {
194:     return N('La Espada de Vael te queda mejor que a mí. Si la rompes, vuelve. Si la pierdes, no vuelvas. Es broma. Más o menos. *ríe y golpea el yunque una vez más*', {
195:       speaker: 'Tovin', role: 'Herrero de Alda',
196:       choices: [
197:         C('¿Puedes mejorar mi armadura?', N('Con lo que me traes, no. Con lo que traerás de Drakmor, quizá. El metal de allí recuerda el fuego. Y el fuego recuerda a los necios que lo desafiaron.', {
198:           speaker: 'Tovin', role: 'Herrero de Alda', next: 'close'
199:         })),
200:         C('Hasta luego.', 'close')
201:       ]
202:     })
203:   }
204:   return N('El yunque está frío y la cerveza caliente. Un desastre en cualquier orden. Si encuentras hierro estelar, tráelo. Si encuentras una historia, cuéntamela. Prefiero las historias: no hay que afilarlas.', {
205:     speaker: 'Tovin', role: 'Herrero de Alda', next: 'close'
206:   })
207: }
208: 
209: // ───────────────────────────── MERA ─────────────────────────────
210: function mera(g) {
211:   if (!g.quests.isActive('flores_altar') && !done(g, 'flores_altar')) {
212:     return N('Cada amanecer enciendo cinco velas por los que no volvieron. Este año no tengo flores de lumen. Crecen cerca del agua y brillan cuando nadie las mira. ¿Me traerías cinco? El altar no exige mucho, pero tampoco olvida.', {
213:       speaker: 'Mera', role: 'Guardiana del altar',
214:       choices: [
215:         C('Traeré las flores.', 'close', () => { g.quests.start('flores_altar'); }),
216:         C('Ahora no puedo.', 'close')
217:       ]
218:     })
219:   }
220:   if (has(g, 'flores_altar')) {
221:     const n = g.inventoryCount('flor_lumen')
222:     return N(n < 5 ? `Llevas ${n} de cinco. Las flores de lumen se esconden entre la hierba alta, cerca del río y del bosque. No las arranques con raíz: mañana querrán volver.` : 'Cinco flores. Huelen a lluvia y a principio. Espera… *las coloca en el altar* El nombre de los caídos se ha vuelto a oír. Gracias, viajero. Toma esto: perteneció a alguien que también volvió.', {
223:       speaker: 'Mera', role: 'Guardiana del altar', next: 'close'
224:     })
225:   }
226:   return N('El altar está completo otra vez. Si alguna vez el Velo te enseña algo que no quieres ver, vuelve aquí. La luz de las velas no juzga; solo acompaña.', {
227:     speaker: 'Mera', role: 'Guardiana del altar', next: 'close'
228:   })
229: }
230: 
231: // ───────────────────────────── BRUNO / LÍA ─────────────────────────────
232: function bruno(g) {
233:   return N('El lago está más profundo de lo que parece. Cuando era niño, mi padre decía que en el fondo duerme una ciudad entera. Yo le creía. Ahora sé que las ciudades no duermen: esperan.', {
234:     speaker: 'Bruno', role: 'Pescador',
235:     choices: [
236:       C('¿Has visto algo extraño en el agua?', N('Una luz, la noche antes de que llegaras. Subía desde el fondo y se quedaba quieta, como si escuchara. Luego oí una espada. No un choque: una respiración.', {
237:         speaker: 'Bruno', role: 'Pescador', next: 'close'
238:       })),
239:       C('¿Algún consejo?', N('No cruces el lago a nado. No por el agua: por lo que hay debajo. Rodea por la orilla y usa los puentes de piedra. Y si ves burbujas que suben al revés, corre.', {
240:         speaker: 'Bruno', role: 'Pescador', next: 'close'
241:       })),
242:       C('Adiós.', 'close')
243:     ]
244:   })
245: }
246: 
247: function lia(g) {
248:   if (g.flags.lia_gift) return N('¡Volviste! ¿La criatura sigue contigo? ¿Puedo verla? Prometo no tocarla. Bueno, solo un poquito.', { speaker: 'Lía', role: 'Voz del pueblo', next: 'close' })
249:   return N('Mi madre dice que las criaturas del bosque se comen a los niños que no obedecen. Pero yo le he dado una flor a una Lumifín y no me ha comido. Creo que mi madre exagera.', {
250:     speaker: 'Lía', role: 'Voz del pueblo',
251:     choices: [
252:       C('¿Dónde viste a la Lumifín?', N('Al otro lado del claro, bajo el sauce grande. Si te acercas despacio y le enseñas una flor de lumen, se queda quieta. Pero no la asustes: su cola brilla más cuando tiene miedo.', {
253:         speaker: 'Lía', role: 'Voz del pueblo', next: 'close'
254:       })),
255:       C('Toma esta flor. (Entregar Flor de Lumen)', 'close', () => {
256:         if (g.inventoryCount('flor_lumen') > 0) { g.removeItem('flor_lumen', 1); g.flags.lia_gift = true; g.addResonance(2); g.toast('Lía te sonríe. Resonancia +2.') }
257:         else g.toast('No tienes ninguna Flor de Lumen.')
258:       }),
259:       C('Adiós.', 'close')
260:     ]
261:   })
262: }
263: 
264: // ───────────────────────────── KAELEN ─────────────────────────────
265: function kaelen(g) {
266:   if (has(g, 'tierras_ceniza')) {
267:     return N('Así que la Puerta de Ceniza sigue aceptando visitantes. Pensé que ya no quedaba nadie al otro lado. Soy Kaelen. Este campamento es lo que queda de Drakmor que no se ha arrodillado ante el Señor de Ceniza.', {
268:       speaker: 'Kaelen', role: 'Último rebelde',
269:       choices: [
270:         C('¿Quién es Varok?', N('Un padre. Un rey. Un hombre que perdió a su hija y decidió declararle la guerra al tiempo. Su dolor se filtró en la tierra y ahora respira por ella. Los ceniceros que ves fuera no son monstruos: son soldados que olvidaron por qué luchaban.', {
271:           speaker: 'Kaelen', role: 'Último rebelde',
272:           choices: [C('¿Qué quieres de mí?', N('La Fortaleza de Varok tiene una puerta que solo se abre desde dentro. Tengo la llave, pero no la fuerza. Tú tienes la fuerza, pero no la llave. Y hay algo más: tres memorias de su hija están esparcidas por el bosque y el santuario. Si las reúnes, quizá puedas hablarle antes de que te mate.', {
273:             speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
274:           }))]
275:         })),
276:         C('He venido a detener la Ruptura.', N('Todos venimos a detener algo. Varok quiere detener la muerte. Yo quiero detener a Varok. Tú querrás detener el Velo. Ninguno lo conseguirá solo. Por eso estamos aquí, alrededor de una hoguera que ya no calienta.', {
277:           speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
278:         }))
279:       ]
280:     })
281:   }
282:   if (just(g, 'tierras_ceniza')) {
283:     return N('Toma la Llave de Ceniza. Abre la puerta de la fortaleza, pero antes busca las tres Memorias de Ceniza: una en el bosque de obsidiana, otra en sus profundidades y una más en el santuario del este. Son recuerdos de la hija de Varok. Si aún queda un padre dentro de él, esas memorias lo encontrarán.', {
284:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
285:     })
286:   }
287:   if (has(g, 'hija_ceniza')) {
288:     return N(`${g.quests.stepProgress('hija_ceniza', 0)} de tres memorias. La del santuario está junto a la lava; la del bosque, donde los árboles tienen más sed. Cuando las tengas, vuelve. No quiero que entres en la fortaleza con las manos vacías.`, {
289:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
290:     })
291:   }
292:   if (just(g, 'hija_ceniza')) {
293:     return N('Conozco esa mirada. Has visto a la niña. Se llamaba Sela. Varok construyó un reino entero para no tener que decir su nombre en pasado. Ahora entra y dile que el tiempo no se detiene: se comparte. Aunque tenga que ser con una espada en la mano.', {
294:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
295:     })
296:   }
297:   if (has(g, 'senor_ceniza')) {
298:     return N('La brecha está abierta. La puerta de la fortaleza te espera al norte, más allá de la grieta. Yo cubriré tu retirada desde aquí. Y forastero… si puedes, no lo mates. Si no puedes, no dejes que su muerte sea en vano.', {
299:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
300:     })
301:   }
302:   if (!g.quests.isActive('faro_ceniza') && !done(g, 'faro_ceniza') && (g.flags.varok_defeated || done(g, 'senor_ceniza'))) {
303:     return N('La fortaleza está en silencio. Pero el faro del sureste sigue apagado, y hay gente perdida en la grieta. Enciéndelo. No te costará nada, y a alguien le costará todo.', {
304:       speaker: 'Kaelen', role: 'Último rebelde',
305:       choices: [
306:         C('Voy a encenderlo.', 'close', () => { g.quests.start('faro_ceniza'); }),
307:         C('Ahora no.', 'close')
308:       ]
309:     })
310:   }
311:   if (done(g, 'senor_ceniza')) {
312:     return N(g.flags.varok_spared
313:       ? 'Le perdonaste. No sé si fue misericordia o crueldad, pero fue tuyo. Varok bajó la espada y por primera vez en años el fuego de la fortaleza no olía a carne.'
314:       : 'Le quitaste todo. Su fuego, su memoria, su nombre. Drakmor está a salvo, pero esta tierra ya no recordará que un padre intentó salvar a su hija. Eso también es una muerte.', {
315:       speaker: 'Kaelen', role: 'Último rebelde',
316:       choices: [
317:         C('¿Qué será de Drakmor?', N('Será lo que hagamos con la ceniza. No con la que cae del cielo: con la que llevamos dentro. La Puerta del Cielo está abierta, al sureste de la fortaleza. Kansordore te espera. Ojalá encuentres allí una respuesta menos dolorosa que la nuestra.', {
318:           speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
319:         })),
320:         C('Cuida de los tuyos.', 'close')
321:       ]
322:     })
323:   }
324:   return N('La ceniza cae más despacio cuando alguien la mira. Quédate junto al fuego si lo necesitas. Mañana el mundo seguirá roto, pero tú estarás un poco menos.', {
325:     speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
326:   })
327: }
328: 
329: // ───────────────────────────── VESNA ─────────────────────────────
330: function vesna(g) {
331:   return N('Ceniza, humo y esperanza. Dos de las tres no se venden, pero tengo pociones para lo otro. ¿Qué necesitas, forastero?', {
332:     speaker: 'Vesna', role: 'Mercader de ceniza',
333:     choices: [
334:       C('Ver mercancía.', 'close', () => g.openShop()),
335:       C('¿Sabes algo de Varok?', N('Sé que paga bien y que no pregunta a quién sirve. Sé que su hija murió cuando la grieta se abrió y que desde entonces el cielo de Drakmor no ha vuelto a amanecer. Hay quien dice que podría salvarse. Yo digo que quien quiere salvar a todos acaba quemando a todos.', {
336:         speaker: 'Vesna', role: 'Mercader de ceniza', next: 'close'
337:       })),
338:       C('Adiós.', 'close')
339:     ]
340:   })
341: }
342: 
343: // ───────────────────────────── SERAPHINE ─────────────────────────────
344: function seraphine(g) {
345:   if (has(g, 'ciudad_cielo')) {
346:     return N('No levantes la espada. Aquí no se combate: se recuerda. Soy Seraphine, la última archivera. Llevo seiscientos años leyendo el mismo libro y aún no he llegado al final. Tú, en cambio, has llegado antes de empezar.', {
347:       speaker: 'Seraphine', role: 'Última archivera',
348:       choices: [
349:         C('¿Qué libro es ese?', N('El Libro del Velo. En sus páginas está escrito este mundo, y también los otros. Cada vez que una página se rompe, nace una región. Cada vez que alguien la lee hasta el final, el mundo vuelve a empezar. Tú hueles a página rota.', {
350:           speaker: 'Seraphine', role: 'Última archivera',
351:           choices: [C('¿Cómo lo detengo?', N('No lo detengas. Lo detenido se pudre. Ábrelo o ciérralo, pero elige. Para eso necesito los tres Sellos del Archivo. Están repartidos por las islas. Tráelos y te mostraré lo que ni yo me atrevo a leer en voz alta.', {
352:             speaker: 'Seraphine', role: 'Última archivera', next: 'close'
353:           }))]
354:         })),
355:         C('¿Por qué me llamas «Jugador Cero»?', N('Porque la profecía no habla de un héroe. Habla de alguien que puede volver a empezar cuando el mundo termina. Alguien que ya ha estado aquí. Alguien que no recuerda cuántas veces. Tú no eres un personaje de esta historia: eres quien la sostiene.', {
356:           speaker: 'Seraphine', role: 'Última archivera', next: 'close'
357:         }))
358:       ]
359:     })
360:   }
361:   if (has(g, 'tres_sellos')) {
362:     const n = g.quests.stepProgress('tres_sellos', 0)
363:     return N(n < 3 ? `${n} de tres sellos. El primero está al oeste, junto al borde del cielo. El segundo al este, en la ciudad de Ael. El tercero donde el Velo es más fino: al norte del templo. No los leas. Los sellos muerden.` : 'Los tres sellos. El Archivo ya reconoce tu mano. Ven, siéntate. Lo que voy a mostrarte no te hará daño, pero quizá te haga recordar que ya lo sabías.', {
364:       speaker: 'Seraphine', role: 'Última archivera', next: 'close'
365:     })
366:   }
367:   if (just(g, 'tres_sellos')) {
368:     return N('Mira. *el Archivo se abre como una flor de papel* Cada línea de este libro es una vida. Aquí estás tú, en la página 1. Y en la 47. Y en la 312. Has salvado Valdoria antes. Has visto arder Drakmor antes. Y siempre, al final, has elegido. Pero alguien ha estado borrando tu nombre entre partidas.', {
369:       speaker: 'Seraphine', role: 'Última archivera',
370:       choices: [
371:         C('¿Quién borra mi nombre?', N('El Custodio del Velo. No por maldad: por miedo. Si recuerdas todas tus vidas, puedes reescribir el libro. Y si puedes reescribirlo, el mundo deja de ser un mundo y se convierte en un borrador. Él prefiere un final triste a ninguna página.', {
372:           speaker: 'Seraphine', role: 'Última archivera',
373:           choices: [C('¿Y tú qué prefieres?', N('Prefiero que alguien elija de verdad, aunque se equivoque. Ve al Templo del Velo, al norte. El Custodio te espera. Y cuando lo enfrentes, recuerda: no estás luchando contra un monstruo. Estás luchando contra una versión de ti que tiene miedo de terminar.', {
374:             speaker: 'Seraphine', role: 'Última archivera', next: 'close'
375:           }))]
376:         })),
377:         C('¿Puedo recuperar mi nombre?', N('Tu nombre no se perdió: lo escondiste. En cada vida elegiste uno distinto. El que llevas ahora es tan real como los otros. La pregunta no es quién fuiste, sino quién quieres ser cuando el libro se cierre.', {
378:           speaker: 'Seraphine', role: 'Última archivera', next: 'close'
379:         }))
380:       ]
381:     })
382:   }
383:   if (has(g, 'jugador_cero')) {
384:     return N('El Custodio no es cruel. Es el guardián de todas las versiones de esta historia. Si le vences, no ganarás: le obligarás a mirar. Ve al templo al norte. Y no olvides que, en alguna página, él también fuiste tú.', {
385:       speaker: 'Seraphine', role: 'Última archivera', next: 'close'
386:     })
387:   }
388:   if (!g.quests.isActive('ecos_pasado') && !done(g, 'ecos_pasado') && (done(g, 'tres_sellos') || g.flags.truth_revealed)) {
389:     return N('Antes de que vayas al templo, hay algo que puedo hacer por ti. He oído ecos de tu nombre en los márgenes del Archivo. Tres fragmentos. Si los escuchas, quizá recuerdes algo que el Custodio no pudo borrar.', {
390:       speaker: 'Seraphine', role: 'Última archivera',
391:       choices: [
392:         C('Buscaré los ecos.', 'close', () => { g.quests.start('ecos_pasado'); }),
393:         C('No quiero saber quién fui.', 'close')
394:       ]
395:     })
396:   }
397:   if (has(g, 'ecos_pasado')) {
398:     return N(`${g.quests.stepProgress('ecos_pasado', 0)} de tres ecos. No los fuerces. Escúchalos como escucharías una canción que se está olvidando.`, {
399:       speaker: 'Seraphine', role: 'Última archivera', next: 'close'
400:     })
401:   }
402:   if (done(g, 'ecos_pasado')) {
403:     return N(g.flags.ending
