.toggle::after { content: ''; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%; background: #8f8a7d; transition: all .2s; }
.toggle.on { background: rgba(228,194,124,.28); border-color: var(--gold-3); }
