231: // ───────────────────────────── BRUNO / LÍA ─────────────────────────────
232: function bruno(g) {
233:   return N('El lago está más profundo de lo que parece. Cuando era niño, mi padre decía que en el fondo duerme una ciudad entera. Yo le creía. Ahora sé que las ciudades no duermen: esperan.', {
234:     speaker: 'Bruno', role: 'Pescador',
235:     choices: [
236:       C('¿Has visto algo extraño en el agua?', N('Una luz, la noche antes de que llegaras. Subía desde el fondo y se quedaba quieta, como si escuchara. Luego oí una espada. No un choque: una respiración.', {
237:         speaker: 'Bruno', role: 'Pescador', next: 'close'
238:       })),
239:       C('¿Algún consejo?', N('No cruces el lago a nado. No por el agua: por lo que hay debajo. Rodea por la orilla y usa los puentes de piedra. Y si ves burbujas que suben al revés, corre.', {
240:         speaker: 'Bruno', role: 'Pescador', next: 'close'
241:       })),
242:       C('Adiós.', 'close')
243:     ]
