329: // ───────────────────────────── VESNA ─────────────────────────────
330: function vesna(g) {
331:   return N('Ceniza, humo y esperanza. Dos de las tres no se venden, pero tengo pociones para lo otro. ¿Qué necesitas, forastero?', {
332:     speaker: 'Vesna', role: 'Mercader de ceniza',
333:     choices: [
334:       C('Ver mercancía.', 'close', () => g.openShop()),
335:       C('¿Sabes algo de Varok?', N('Sé que paga bien y que no pregunta a quién sirve. Sé que su hija murió cuando la grieta se abrió y que desde entonces el cielo de Drakmor no ha vuelto a amanecer. Hay quien dice que podría salvarse. Yo digo que quien quiere salvar a todos acaba quemando a todos.', {
336:         speaker: 'Vesna', role: 'Mercader de ceniza', next: 'close'
337:       })),
338:       C('Adiós.', 'close')
339:     ]
340:   })
