343: // ───────────────────────────── SERAPHINE ─────────────────────────────
344: function seraphine(g) {
345:   if (has(g, 'ciudad_cielo')) {
346:     return N('No levantes la espada. Aquí no se combate: se recuerda. Soy Seraphine, la última archivera. Llevo seiscientos años leyendo el mismo libro y aún no he llegado al final. Tú, en cambio, has llegado antes de empezar.', {
347:       speaker: 'Seraphine', role: 'Última archivera',
348:       choices: [
349:         C('¿Qué libro es ese?', N('El Libro del Velo. En sus páginas está escrito este mundo, y también los otros. Cada vez que una página se rompe, nace una región. Cada vez que alguien la lee hasta el final, el mundo vuelve a empezar. Tú hueles a página rota.', {
350:           speaker: 'Seraphine', role: 'Última archivera',
351:           choices: [C('¿Cómo lo detengo?', N('No lo detengas. Lo detenido se pudre. Ábrelo o ciérralo, pero elige. Para eso necesito los tres Sellos del Archivo. Están repartidos por las islas. Tráelos y te mostraré lo que ni yo me atrevo a leer en voz alta.', {
352:             speaker: 'Seraphine', role: 'Última archivera', next: 'close'
353:           }))]
354:         })),
355:         C('¿Por qué me llamas «Jugador Cero»?', N('Porque la profecía no habla de un héroe. Habla de alguien que puede volver a empezar cuando el mundo termina. Alguien que ya ha estado aquí. Alguien que no recuerda cuántas veces. Tú no eres un personaje de esta historia: eres quien la sostiene.', {
356:           speaker: 'Seraphine', role: 'Última archivera', next: 'close'
357:         }))
358:       ]
359:     })
360:   }
361:   if (has(g, 'tres_sellos')) {
362:     const n = g.quests.stepProgress('tres_sellos', 0)
363:     return N(n < 3 ? `${n} de tres sellos. El primero está al oeste, junto al borde del cielo. El segundo al este, en la ciudad de Ael. El tercero donde el Velo es más fino: al norte del templo. No los leas. Los sellos muerden.` : 'Los tres sellos. El Archivo ya reconoce tu mano. Ven, siéntate. Lo que voy a mostrarte no te hará daño, pero quizá te haga recordar que ya lo sabías.', {
364:       speaker: 'Seraphine', role: 'Última archivera', next: 'close'
365:     })
366:   }
367:   if (just(g, 'tres_sellos')) {
368:     return N('Mira. *el Archivo se abre como una flor de papel* Cada línea de este libro es una vida. Aquí estás tú, en la página 1. Y en la 47. Y en la 312. Has salvado Valdoria antes. Has visto arder Drakmor antes. Y siempre, al final, has elegido. Pero alguien ha estado borrando tu nombre entre partidas.', {
369:       speaker: 'Seraphine', role: 'Última archivera',
370:       choices: [
371:         C('¿Quién borra mi nombre?', N('El Custodio del Velo. No por maldad: por miedo. Si recuerdas todas tus vidas, puedes reescribir el libro. Y si puedes reescribirlo, el mundo deja de ser un mundo y se convierte en un borrador. Él prefiere un final triste a ninguna página.', {
372:           speaker: 'Seraphine', role: 'Última archivera',
373:           choices: [C('¿Y tú qué prefieres?', N('Prefiero que alguien elija de verdad, aunque se equivoque. Ve al Templo del Velo, al norte. El Custodio te espera. Y cuando lo enfrentes, recuerda: no estás luchando contra un monstruo. Estás luchando contra una versión de ti que tiene miedo de terminar.', {
374:             speaker: 'Seraphine', role: 'Última archivera', next: 'close'
375:           }))]
376:         })),
377:         C('¿Puedo recuperar mi nombre?', N('Tu nombre no se perdió: lo escondiste. En cada vida elegiste uno distinto. El que llevas ahora es tan real como los otros. La pregunta no es quién fuiste, sino quién quieres ser cuando el libro se cierre.', {
378:           speaker: 'Seraphine', role: 'Última archivera', next: 'close'
379:         }))
380:       ]
381:     })
382:   }
383:   if (has(g, 'jugador_cero')) {
384:     return N('El Custodio no es cruel. Es el guardián de todas las versiones de esta historia. Si le vences, no ganarás: le obligarás a mirar. Ve al templo al norte. Y no olvides que, en alguna página, él también fuiste tú.', {
385:       speaker: 'Seraphine', role: 'Última archivera', next: 'close'
386:     })
387:   }
388:   if (!g.quests.isActive('ecos_pasado') && !done(g, 'ecos_pasado') && (done(g, 'tres_sellos') || g.flags.truth_revealed)) {
389:     return N('Antes de que vayas al templo, hay algo que puedo hacer por ti. He oído ecos de tu nombre en los márgenes del Archivo. Tres fragmentos. Si los escuchas, quizá recuerdes algo que el Custodio no pudo borrar.', {
390:       speaker: 'Seraphine', role: 'Última archivera',
391:       choices: [
392:         C('Buscaré los ecos.', 'close', () => { g.quests.start('ecos_pasado'); }),
393:         C('No quiero saber quién fui.', 'close')
394:       ]
395:     })
396:   }
397:   if (has(g, 'ecos_pasado')) {
398:     return N(`${g.quests.stepProgress('ecos_pasado', 0)} de tres ecos. No los fuerces. Escúchalos como escucharías una canción que se está olvidando.`, {
399:       speaker: 'Seraphine', role: 'Última archivera', next: 'close'
400:     })
401:   }
402:   if (done(g, 'ecos_pasado')) {
403:     return N(g.flags.ending
404:       ? 'El libro sigue abierto. O cerrado. Ya no importa: ahora hay alguien que recuerda haber elegido. Eso es más de lo que este mundo había tenido nunca.'
405:       : 'Los ecos dicen que fuiste niño, que tuviste miedo, que quisiste salvar a alguien y no pudiste. También dicen que volviste a intentarlo. Eso no es debilidad. Es la definición de un jugador.', {
406:       speaker: 'Seraphine', role: 'Última archivera', next: 'close'
407:     })
408:   }
409:   return N('La biblioteca respira contigo. Los libros duermen, pero sueñan con lectores. Si alguna vez el mundo se acaba, ven aquí: encontraremos una página en blanco y empezaremos por el principio.', {
410:     speaker: 'Seraphine', role: 'Última archivera',
411:     choices: [
412:       C('¿Qué es la Convergencia Absoluta?', N('El momento en que todas las versiones del mundo intentan existir a la vez. La mayoría de las veces se destruyen. Algunas veces, alguien elige una y las demás aceptan desvanecerse. Eso es la Ascensión: no subir, sino aceptar.', {
413:         speaker: 'Seraphine', role: 'Última archivera', next: 'close'
414:       })),
415:       C('Adiós.', 'close')
416:     ]
417:   })
418: }
