442:       ]
443:     })
444:   },
445:   varok_after(g) {
446:     return N('*Varok cae de rodillas. La hoja de ceniza se apaga.* No… Sela… el tiempo… todavía puedo… *te mira, y por un instante el fuego de sus ojos es solo el de un padre* Hazlo. Llévate la Lágrima. Pero antes dime: ¿la has visto? ¿La has oído en las memorias?', {
447:       speaker: 'Varok', role: 'Señor de Ceniza',
448:       choices: [
449:         C('La he visto. Está en paz.', N('Entonces… quizá yo también pueda estarlo. *cierra los ojos* Gracias, forastero. No por perdonarme. Por no mentirme.', {
450:           speaker: 'Varok', role: 'Señor de Ceniza', next: 'close'
451:         }), () => g.spareVarok()),
452:         C('Su memoria es mía ahora.', N('*el fuego vuelve a sus ojos, deformado* Entonces no eres distinto de mí. Llévatela. Llévatelo todo. Y cuando el Velo te devore, recuerda que te lo advertí.', {
453:           speaker: 'Varok', role: 'Señor de Ceniza', next: 'close'
454:         }), () => g.consumeVarok())
455:       ]
456:     })
457:   },
458:   custodio_intro(g) {
459:     return N('Detente, Jugador Cero. He contado tus pasos en trescientas doce versiones de esta historia. Siempre llegas aquí. Siempre dudas. Y siempre eliges algo que alguien lamenta.', {
460:       speaker: 'Custodio del Velo', role: 'El último guardián de la historia',
461:       choices: [
462:         C('¿Quién eres tú?', N('Soy lo que queda de ti cuando terminas una partida. El eco que se niega a apagarse. Cada vez que el Velo se rompe, alguien tiene que recoger los pedazos y empezar de nuevo. Ese alguien soy yo. Ese alguien podrías ser tú.', {
463:           speaker: 'Custodio del Velo', role: 'El último guardián de la historia', next: () => N('Si abres el Velo, el mundo dejará de ser una historia y se convertirá en una herida. Si lo cierras, todos los que amas dormirán para siempre en una página que nadie volverá a leer. Elige.', {
464:             speaker: 'Custodio del Velo', role: 'El último guardián de la historia',
465:             choices: [
466:               C('No elegiré por miedo.', 'close', () => g.startBossFight('custodio_velo')),
467:               C('Entonces ayúdame a elegir.', N('No puedo. Si te ayudara, dejaría de ser tu guardián y me convertiría en tu cómplice. Y los cómplices se olvidan. Los guardianes, no.', {
468:                 speaker: 'Custodio del Velo', role: 'El último guardián de la historia',
469:                 choices: [C('Lo siento.', 'close', () => g.startBossFight('custodio_velo'))]
470:               }))
471:             ]
472:           }))
473:         })),
474:         C('Apártate.', N('No puedo. Pero puedes hacerme apartar. *alza la lanza* Que la Espada Celestial decida si este mundo merece un final escrito por su propio protagonista.', {
475:           speaker: 'Custodio del Velo', role: 'El último guardián de la historia',
476:           choices: [C('Que así sea.', 'close', () => g.startBossFight('custodio_velo'))]
477:         }))
478:       ]
479:     })
480:   },
481:   custodio_after(g) {
482:     return N('*El Custodio se deshace en páginas.* No… era el último… si me borras, nadie recordará las otras vidas… nadie sabrá cuánto costó llegar hasta aquí… *una página se posa en tu mano* Llévala. Y elige mejor de lo que yo supe.', {
483:       speaker: 'Custodio del Velo', role: 'El último guardián de la historia', next: 'close'
484:     })
485:   },
486:   convergence_intro(g) {
487:     return N('*La Convergencia tiene tu rostro. Detrás de ella, cientos de rostros más: todas las versiones de ti que llegaron antes.* Has vuelto. Otra vez. Podría decirte que esta vez será distinto, pero ambos sabemos que mentiría. La Espada está ahí. El Velo se rompe. Solo falta que decidas qué clase de final merece el mundo.', {
488:       speaker: 'La Convergencia', role: 'Jugador Cero',
489:       choices: [
490:         C('Ya no soy el que empezó este viaje.', N('Eso es lo que todos dicen antes de convertirse en mí. *sonríe* Demuéstralo. Si tu voluntad es más fuerte que la suma de tus vidas, quizá esta vez el libro se cierre de otra forma.', {
491:           speaker: 'La Convergencia', role: 'Jugador Cero',
492:           choices: [C('Desenvaino la Espada Celestial.', 'close', () => g.startBossFight('convergencia'))]
493:         })),
494:         C('¿Qué elegirías tú?', N('Elegiría no volver a elegir. Pero eso ya no es una opción. *la Espada Celestial aparece entre ambos* Tómala. Y esta vez, hazlo por alguien que no seas tú.', {
495:           speaker: 'La Convergencia', role: 'Jugador Cero',
496:           choices: [C('La tomo.', 'close', () => g.startBossFight('convergencia'))]
497:         }))
498:       ]
499:     })
