247: function lia(g) {
248:   if (g.flags.lia_gift) return N('¡Volviste! ¿La criatura sigue contigo? ¿Puedo verla? Prometo no tocarla. Bueno, solo un poquito.', { speaker: 'Lía', role: 'Voz del pueblo', next: 'close' })
249:   return N('Mi madre dice que las criaturas del bosque se comen a los niños que no obedecen. Pero yo le he dado una flor a una Lumifín y no me ha comido. Creo que mi madre exagera.', {
250:     speaker: 'Lía', role: 'Voz del pueblo',
251:     choices: [
252:       C('¿Dónde viste a la Lumifín?', N('Al otro lado del claro, bajo el sauce grande. Si te acercas despacio y le enseñas una flor de lumen, se queda quieta. Pero no la asustes: su cola brilla más cuando tiene miedo.', {
253:         speaker: 'Lía', role: 'Voz del pueblo', next: 'close'
254:       })),
255:       C('Toma esta flor. (Entregar Flor de Lumen)', 'close', () => {
256:         if (g.inventoryCount('flor_lumen') > 0) { g.removeItem('flor_lumen', 1); g.flags.lia_gift = true; g.addResonance(2); g.toast('Lía te sonríe. Resonancia +2.') }
257:         else g.toast('No tienes ninguna Flor de Lumen.')
258:       }),
259:       C('Adiós.', 'close')
260:     ]
261:   })
262: }
