264: // ───────────────────────────── KAELEN ─────────────────────────────
265: function kaelen(g) {
266:   if (has(g, 'tierras_ceniza')) {
267:     return N('Así que la Puerta de Ceniza sigue aceptando visitantes. Pensé que ya no quedaba nadie al otro lado. Soy Kaelen. Este campamento es lo que queda de Drakmor que no se ha arrodillado ante el Señor de Ceniza.', {
268:       speaker: 'Kaelen', role: 'Último rebelde',
269:       choices: [
270:         C('¿Quién es Varok?', N('Un padre. Un rey. Un hombre que perdió a su hija y decidió declararle la guerra al tiempo. Su dolor se filtró en la tierra y ahora respira por ella. Los ceniceros que ves fuera no son monstruos: son soldados que olvidaron por qué luchaban.', {
271:           speaker: 'Kaelen', role: 'Último rebelde',
272:           choices: [C('¿Qué quieres de mí?', N('La Fortaleza de Varok tiene una puerta que solo se abre desde dentro. Tengo la llave, pero no la fuerza. Tú tienes la fuerza, pero no la llave. Y hay algo más: tres memorias de su hija están esparcidas por el bosque y el santuario. Si las reúnes, quizá puedas hablarle antes de que te mate.', {
273:             speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
274:           }))]
275:         })),
276:         C('He venido a detener la Ruptura.', N('Todos venimos a detener algo. Varok quiere detener la muerte. Yo quiero detener a Varok. Tú querrás detener el Velo. Ninguno lo conseguirá solo. Por eso estamos aquí, alrededor de una hoguera que ya no calienta.', {
277:           speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
278:         }))
279:       ]
280:     })
281:   }
282:   if (just(g, 'tierras_ceniza')) {
283:     return N('Toma la Llave de Ceniza. Abre la puerta de la fortaleza, pero antes busca las tres Memorias de Ceniza: una en el bosque de obsidiana, otra en sus profundidades y una más en el santuario del este. Son recuerdos de la hija de Varok. Si aún queda un padre dentro de él, esas memorias lo encontrarán.', {
284:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
285:     })
286:   }
287:   if (has(g, 'hija_ceniza')) {
288:     return N(`${g.quests.stepProgress('hija_ceniza', 0)} de tres memorias. La del santuario está junto a la lava; la del bosque, donde los árboles tienen más sed. Cuando las tengas, vuelve. No quiero que entres en la fortaleza con las manos vacías.`, {
289:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
290:     })
291:   }
292:   if (just(g, 'hija_ceniza')) {
293:     return N('Conozco esa mirada. Has visto a la niña. Se llamaba Sela. Varok construyó un reino entero para no tener que decir su nombre en pasado. Ahora entra y dile que el tiempo no se detiene: se comparte. Aunque tenga que ser con una espada en la mano.', {
294:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
295:     })
296:   }
297:   if (has(g, 'senor_ceniza')) {
298:     return N('La brecha está abierta. La puerta de la fortaleza te espera al norte, más allá de la grieta. Yo cubriré tu retirada desde aquí. Y forastero… si puedes, no lo mates. Si no puedes, no dejes que su muerte sea en vano.', {
299:       speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
300:     })
301:   }
302:   if (!g.quests.isActive('faro_ceniza') && !done(g, 'faro_ceniza') && (g.flags.varok_defeated || done(g, 'senor_ceniza'))) {
303:     return N('La fortaleza está en silencio. Pero el faro del sureste sigue apagado, y hay gente perdida en la grieta. Enciéndelo. No te costará nada, y a alguien le costará todo.', {
304:       speaker: 'Kaelen', role: 'Último rebelde',
305:       choices: [
306:         C('Voy a encenderlo.', 'close', () => { g.quests.start('faro_ceniza'); }),
307:         C('Ahora no.', 'close')
308:       ]
309:     })
310:   }
311:   if (done(g, 'senor_ceniza')) {
312:     return N(g.flags.varok_spared
313:       ? 'Le perdonaste. No sé si fue misericordia o crueldad, pero fue tuyo. Varok bajó la espada y por primera vez en años el fuego de la fortaleza no olía a carne.'
314:       : 'Le quitaste todo. Su fuego, su memoria, su nombre. Drakmor está a salvo, pero esta tierra ya no recordará que un padre intentó salvar a su hija. Eso también es una muerte.', {
315:       speaker: 'Kaelen', role: 'Último rebelde',
316:       choices: [
317:         C('¿Qué será de Drakmor?', N('Será lo que hagamos con la ceniza. No con la que cae del cielo: con la que llevamos dentro. La Puerta del Cielo está abierta, al sureste de la fortaleza. Kansordore te espera. Ojalá encuentres allí una respuesta menos dolorosa que la nuestra.', {
318:           speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
319:         })),
320:         C('Cuida de los tuyos.', 'close')
321:       ]
322:     })
323:   }
324:   return N('La ceniza cae más despacio cuando alguien la mira. Quédate junto al fuego si lo necesitas. Mañana el mundo seguirá roto, pero tú estarás un poco menos.', {
325:     speaker: 'Kaelen', role: 'Último rebelde', next: 'close'
326:   })
327: }
328: 
329: // ───────────────────────────── VESNA ─────────────────────────────
330: function vesna(g) {
331:   return N('Ceniza, humo y esperanza. Dos de las tres no se venden, pero tengo pociones para lo otro. ¿Qué necesitas, forastero?', {
332:     speaker: 'Vesna', role: 'Mercader de ceniza',
333:     choices: [
334:       C('Ver mercancía.', 'close', () => g.openShop()),
335:       C('¿Sabes algo de Varok?', N('Sé que paga bien y que no pregunta a quién sirve. Sé que su hija murió cuando la grieta se abrió y que desde entonces el cielo de Drakmor no ha vuelto a amanecer. Hay quien dice que podría salvarse. Yo digo que quien quiere salvar a todos acaba quemando a todos.', {
336:         speaker: 'Vesna', role: 'Mercader de ceniza', next: 'close'
337:       })),
338:       C('Adiós.', 'close')
339:     ]
340:   })
341: }
342: 
343: // ───────────────────────────── SERAPHINE ─────────────────────────────
344: function seraphine(g) {
345:   if (has(g, 'ciudad_cielo')) {
346:     return N('No levantes la espada. Aquí no se combate: se recuerda. Soy Seraphine, la última archivera. Llevo seiscientos años leyendo el mismo libro y aún no he llegado al final. Tú, en cambio, has llegado antes de empezar.', {
347:       speaker: 'Seraphine', role: 'Última archivera',
348:       choices: [
349:         C('¿Qué libro es ese?', N('El Libro del Velo. En sus páginas está escrito este mundo, y también los otros. Cada vez que una página se rompe, nace una región. Cada vez que alguien la lee hasta el final, el mundo vuelve a empezar. Tú hueles a página rota.', {
350:           speaker: 'Seraphine', role: 'Última archivera',
351:           choices: [C('¿Cómo lo detengo?', N('No lo detengas. Lo detenido se pudre. Ábrelo o ciérralo, pero elige. Para eso necesito los tres Sellos del Archivo. Están repartidos por las islas. Tráelos y te mostraré lo que ni yo me atrevo a leer en voz alta.', {
352:             speaker: 'Seraphine', role: 'Última archivera', next: 'close'
353:           }))]
354:         })),
355:         C('¿Por qué me llamas «Jugador Cero»?', N('Porque la profecía no habla de un héroe. Habla de alguien que puede volver a empezar cuando el mundo termina. Alguien que ya ha estado aquí. Alguien que no recuerda cuántas veces. Tú no eres un personaje de esta historia: eres quien la sostiene.', {
356:           speaker: 'Seraphine', role: 'Última archivera', next: 'close'
357:         }))
358:       ]
359:     })
360:   }
361:   if (has(g, 'tres_sellos')) {
362:     const n = g.quests.stepProgress('tres_sellos', 0)
363:     return N(n < 3 ? `${n} de tres sellos. El primero está al oeste, junto al borde del cielo. El segundo al este, en la ciudad de Ael. El tercero donde el Velo es más fino: al norte del templo. No los leas. Los sellos muerden.` : 'Los tres sellos. El Archivo ya reconoce tu mano. Ven, siéntate. Lo que voy a mostrarte no te hará daño, pero quizá te haga recordar que ya lo sabías.', {
364:       speaker: 'Seraphine', role: 'Última archivera', next: 'close'
365:     })
366:   }
367:   if (just(g, 'tres_sellos')) {
368:     return N('Mira. *el Archivo se abre como una flor de papel* Cada línea de este libro es una vida. Aquí estás tú, en la página 1. Y en la 47. Y en la 312. Has salvado Valdoria antes. Has visto arder Drakmor antes. Y siempre, al final, has elegido. Pero alguien ha estado borrando tu nombre entre partidas.', {
369:       speaker: 'Seraphine', role: 'Última archivera',
370:       choices: [
371:         C('¿Quién borra mi nombre?', N('El Custodio del Velo. No por maldad: por miedo. Si recuerdas todas tus vidas, puedes reescribir el libro. Y si puedes reescribirlo, el mundo deja de ser un mundo y se convierte en un borrador. Él prefiere un final triste a ninguna página.', {
372:           speaker: 'Seraphine', role: 'Última archivera',
373:           choices: [C('¿Y tú qué prefieres?', N('Prefiero que alguien elija de verdad, aunque se equivoque. Ve al Templo del Velo, al norte. El Custodio te espera. Y cuando lo enfrentes, recuerda: no estás luchando contra un monstruo. Estás luchando contra una versión de ti que tiene miedo de terminar.', {
374:             speaker: 'Seraphine', role: 'Última archivera', next: 'close'
375:           }))]
376:         })),
377:         C('¿Puedo recuperar mi nombre?', N('Tu nombre no se perdió: lo escondiste. En cada vida elegiste uno distinto. El que llevas ahora es tan real como los otros. La pregunta no es quién fuiste, sino quién quieres ser cuando el libro se cierre.', {
378:           speaker: 'Seraphine', role: 'Última archivera', next: 'close'
379:         }))
380:       ]
381:     })
382:   }
383:   if (has(g, 'jugador_cero')) {
384:     return N('El Custodio no es cruel. Es el guardián de todas las versiones de esta historia. Si le vences, no ganarás: le obligarás a mirar. Ve al templo al norte. Y no olvides que, en alguna página, él también fuiste tú.', {
385:       speaker: 'Seraphine', role: 'Última archivera', next: 'close'
