5: const N = (text, extra = {}) => ({ text, ...extra })
6: const C = (label, to, act, extra = {}) => ({ label, to, act, ...extra })
7: 
8: function has(g, id) { return g.quests.isActive(id) }
9: function done(g, id) { return g.quests.isComplete(id) }
10: function just(g, id) { return g.quests.wasJustCompleted(id) }
11: 
12: // ───────────────────────────── IRIA ─────────────────────────────
13: function iria(g) {
14:   const q = g.quests
15:   if (has(g, 'despertar')) {
16:     const askSword = N('Esta hoja es un fragmento de la Gema Celestial, la primera cosa que existió antes de que existiera el tiempo. El Velo la partió en tres: una hoja, una jarra y una lágrima. Tú llevas la hoja. No por casualidad.', {
17:       speaker: 'Anciana Iria', role: 'Memoria de Valdoria',
18:       choices: [
19:         C('¿Qué es el Velo?', N('La membrana entre lo que es y lo que podría ser. Cuando adelgaza, los recuerdos se caen de las cosas y las criaturas olvidan su nombre. Por eso los corrompidos ya no saben que fueron personas.', {
20:           speaker: 'Anciana Iria', role: 'Memoria de Valdoria',
21:           choices: [C('¿Y la profecía?', N('Habla de un Jugador Cero: alguien de fuera de la historia que puede volver a empezar. Durante siglos hemos esperado a un héroe. Quizá nos equivocamos de palabra.', {
22:             speaker: 'Anciana Iria', role: 'Memoria de Valdoria',
23:             next: () => iriaAccept(g)
24:           }))]
25:         })),
26:         C('¿Quién soy yo?', N('No lo sé. Y esa es la primera cosa honesta que puedo decirte. Te encontré en la orilla con el agua en los pulmones y la espada brillando como si te reconociera. Elegiste un nombre al despertar. Ahora tendrás que elegir lo demás.', {
27:           speaker: 'Anciana Iria', role: 'Memoria de Valdoria',
28:           next: () => iriaAccept(g)
29:         })),
30:         C('No quiero ser un héroe.', N('Nadie quiere. Los héroes son quienes se levantan después de la duda, no quienes nunca la tuvieron. Quédate un día. Si el río vuelve a llamarte, sabrás qué hacer.', {
31:           speaker: 'Anciana Iria', role: 'Memoria de Valdoria',
32:           next: () => iriaAccept(g)
33:         }))
34:       ]
35:     })
36:     return askSword
37:   }
38:   if (just(g, 'sombras_ribera')) {
39:     return N('Los corrompidos han retrocedido, pero no están derrotados. Alguien los llamó desde las ruinas, y ese alguien lleva mil años esperando. Antes de que vayas, busca a Nara en el bosque de Lumen. Ella enseña a escuchar lo que las criaturas esconden.', {
40:       speaker: 'Anciana Iria', role: 'Memoria de Valdoria',
41:       choices: [
42:         C('¿Qué hay en las ruinas?', N('La Jarra de Origen. El primer recuerdo del mundo, guardado en barro que nunca se secó. Y bajo ella, un guardián que no distingue entre proteger y aprisionar. Lleva luz. Lleva paciencia. Lleva a alguien contigo.', {
43:           speaker: 'Anciana Iria', role: 'Memoria de Valdoria', next: 'close'
44:         })),
45:         C('Iré a ver a Nara.', 'close')
46:       ]
47:     })
48:   }
49:   if (has(g, 'don_resonancia')) {
50:     return N('Nara te espera en el bosque, al norte. No vayas con la espada desenvainada. Las criaturas huelen el miedo y la prisa. Y tú, criatura mía, hueles a las dos cosas.', {
51:       speaker: 'Anciana Iria', role: 'Memoria de Valdoria', next: 'close'
52:     })
53:   }
54:   if (just(g, 'don_resonancia')) {
55:     return N('Un vínculo verdadero. Ya no estás solo en este mundo. Las ruinas de Vael aguardan al oeste, entre los árboles retorcidos. Enciende sus tres braseros: la Jarra solo responde a la luz que se ofrece, no a la que se roba.', {
56:       speaker: 'Anciana Iria', role: 'Memoria de Valdoria',
57:       choices: [
58:         C('¿Qué ocurrirá cuando la tenga?', N('El Velo temblará. Drakmor lo sentirá antes que nosotros. Y tú tendrás que decidir si la Jarra es un recuerdo que se guarda o una puerta que se abre. Yo ya no puedo decidir por ti.', {
59:           speaker: 'Anciana Iria', role: 'Memoria de Valdoria', next: 'close'
60:         })),
61:         C('Parto hacia Vael.', 'close')
62:       ]
63:     })
64:   }
65:   if (has(g, 'ruinas_vael')) {
66:     return N('Los braseros de Vael llevan siglos apagados. La luz de tu espada puede despertarlos. Y cuando lo hagas, no huyas de lo que salga de la tierra: escúchalo. Hasta los guardianes tienen una razón.', {
67:       speaker: 'Anciana Iria', role: 'Memoria de Valdoria', next: 'close'
68:     })
69:   }
70:   if (just(g, 'ruinas_vael') || g.flags.jar_obtained) {
71:     return N('La Jarra de Origen. La sostienes como si pesara, pero no pesa: recuerda. Escucha su agua cuando el mundo se quede en silencio. Y ve al este, a la Puerta de Ceniza. Drakmor arde, y el fuego tiene memoria.', {
72:       speaker: 'Anciana Iria', role: 'Memoria de Valdoria',
73:       choices: [
74:         C('¿Vendrás conmigo?', N('Mi lugar es este umbral. Alguien tiene que recordar a los que no vuelven. Pero estaré aquí cuando regreses, aunque el Velo intente convencerme de lo contrario.', {
75:           speaker: 'Anciana Iria', role: 'Memoria de Valdoria', next: 'close'
76:         })),
77:         C('Cuida de Alda hasta mi regreso.', 'close')
78:       ]
79:     })
80:   }
81:   if (has(g, 'puerta_ceniza')) {
82:     return N('La Puerta de Ceniza está al este, más allá de la colina del vigía. No es una puerta que se cruce: es una puerta que se recuerda. Lleva la Jarra en alto y el camino aparecerá.', {
83:       speaker: 'Anciana Iria', role: 'Memoria de Valdoria', next: 'close'
84:     })
85:   }
86:   return N('El río sigue cantando, aunque ya nadie recuerde la letra. Descansa cuando lo necesites. La espada no te pide que corras: te pide que vuelvas.', {
87:     speaker: 'Anciana Iria', role: 'Memoria de Valdoria',
88:     choices: [
89:       C('Háblame de la Gema Celestial.', N('Antes de los reinos, antes de los nombres, hubo una gema que contenía todas las posibilidades. Un día se miró a sí misma y quiso saber qué se sentía al elegir. Se rompió. Todo lo demás es la consecuencia.', {
90:         speaker: 'Anciana Iria', role: 'Memoria de Valdoria', next: 'close'
91:       })),
92:       C('Háblame del Jugador Cero.', N('Una figura de la profecía que no pertenece a ningún linaje. No nace: aparece. No hereda: elige. Algunos dicen que es un castigo. Yo creo que es la única forma en que el mundo puede perdonarse.', {
93:         speaker: 'Anciana Iria', role: 'Memoria de Valdoria', next: 'close'
94:       })),
95:       C('Descansar.', 'close')
96:     ]
97:   })
98: }
