18: export function equipmentStats(equipment) {
19:   const out = emptyStats()
20:   for (const id of Object.values(equipment)) {
21:     if (!id) continue
22:     const it = item(id)
23:     if (it.stats) for (const [k, v] of Object.entries(it.stats)) out[k] = (out[k] || 0) + v
