32: export function derive(stats, equipment, level = 1) {
33:   const total = { ...stats }
34:   const bonus = equipmentStats(equipment)
35:   for (const k of Object.keys(total)) total[k] += bonus[k] || 0
36:   const hp = Math.round(90 + total.vitalidad * 8 + level * 6)
37:   const mp = Math.round(45 + total.mana * 4)
38:   const stamina = Math.round(80 + total.resistencia * 4)
39:   const attack = (weaponDamage(equipment) + total.fuerza * 1.4 + level * .6)
40:   const reduction = total.defensa / (total.defensa + 58)
41:   const speed = 6.0 + total.velocidad * .055
42:   const power = 1 + total.inteligencia * .035
43:   const crit = Math.min(.65, .05 + total.suerte * .006)
44:   const capture = 1 + total.suerte * .01
45:   return {
46:     total, hp, mp, stamina, attack, reduction, speed, power, crit, capture,
47:     hpRegen: .35 + total.vitalidad * .022,
48:     manaRegen: 1.9 + total.mana * .05,
49:     staminaRegen: 13 + total.resistencia * .32,
50:     critMult: 1.65 + total.suerte * .01,
51:     dodgeCost: Math.max(16, 23 - total.resistencia * .12),
52:     blockCost: Math.max(4, 10 - total.defensa * .06),
53:     powerSkill: 1 + total.inteligencia * .045
54:   }
55: }
