110: // ───────────────────────────── NARA ─────────────────────────────
111: function nara(g) {
112:   if (has(g, 'don_resonancia')) {
113:     const step = g.quests.stepIndex('don_resonancia')
114:     if (step <= 0) {
115:       return N('No mates a la criatura. Ya sé que la espada te lo pide. Las espadas siempre piden lo fácil. Déjala débil, pero viva, y ofrecele tu mano. Si acepta, la luz de tu pecho cambiará de color un instante.', {
116:         speaker: 'Nara', role: 'Cazadora de ecos',
117:         choices: [
118:           C('¿Cómo sé cuándo está débil?', N('Cuando su nombre brille en tu mente. Cuando la barra de vida esté por debajo de un tercio, pulsa el vínculo. Si falla, no insistas como un ladrón: espera, vuelve a intentarlo. La confianza también tiene enfriamiento.', {
119:             speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
120:           })),
121:           C('¿Y si no quiere venir?', N('Entonces no viene. Un vínculo forzado es una jaula con otro nombre. Pero no te preocupes: casi todas las criaturas están cansadas de estar solas. Como nosotros.', {
122:             speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
123:           }))
124:         ]
125:       })
126:     }
127:     if (step === 1) {
128:       return N('Ve a por una. Las Lumifín duermen bajo los sauces, al este del claro. No corras hacia ellas: camina. Y cuando la captures, vuelve. Quiero ver la cara que pones.', {
129:         speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
130:       })
131:     }
132:   }
133:   if (just(g, 'don_resonancia') || (done(g, 'don_resonancia') && !g.flags.nara_bond)) {
134:     g.flags.nara_bond = true
135:     return N('No has domesticado una criatura. Has aceptado que otra vida importe más que tu prisa. Eso, forastero, es la primera lección de la Resonancia. La segunda la aprenderás cuando tengas que despedirte de ella.', {
136:       speaker: 'Nara', role: 'Cazadora de ecos',
137:       choices: [
138:         C('¿Las criaturas mueren?', N('Todo muere. Pero un vínculo deja un eco, y los ecos encuentran el camino de vuelta. Por eso el Velo tiene miedo de nosotros: no puede borrar lo que se comparte.', {
139:           speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
140:         })),
141:         C('Gracias, Nara.', 'close')
142:       ]
143:     })
144:   }
145:   if (!g.quests.isActive('cazador_ecos') && !done(g, 'cazador_ecos') && (done(g, 'don_resonancia') || g.flags.nara_bond)) {
146:     return N('Tengo un encargo para ti, si te atreves. Tres criaturas distintas, tres vínculos. No por coleccionar: por demostrar que puedes escuchar más de una canción sin desafinar.', {
147:       speaker: 'Nara', role: 'Cazadora de ecos',
148:       choices: [
149:         C('Acepto el desafío.', 'close', () => { g.quests.start('cazador_ecos'); }),
150:         C('Más adelante.', 'close')
151:       ]
152:     })
153:   }
154:   if (has(g, 'cazador_ecos')) {
155:     const n = g.quests.stepProgress('cazador_ecos', 0)
156:     return N(`${n >= 3 ? 'Tres canciones distintas. Lo sabía.' : `${n} de tres. Sigue escuchando.`} Las criaturas no son armas. Son testigos de lo que el Velo intenta borrar. Cuídalas y ellas te cuidarán cuando la espada no baste.`, {
157:       speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
158:     })
159:   }
160:   return N('El bosque está inquieto. Las Lumifín cantan en frecuencias que los humanos no oímos, pero tú no eres del todo humano, ¿verdad? Si alguna vez quieres saber qué eres, pregúntale a las criaturas. Ellas recuerdan más de lo que admiten.', {
161:     speaker: 'Nara', role: 'Cazadora de ecos',
162:     choices: [
163:       C('¿Conoces la Profecía de Jugador Cero?', N('Mi abuela la recitaba como una canción de cuna. «El que no tiene nombre elegirá el final; el que tiene nombre lo vivirá». Nunca supe si era una promesa o una advertencia.', {
164:         speaker: 'Nara', role: 'Cazadora de ecos', next: 'close'
165:       })),
166:       C('Adiós.', 'close')
167:     ]
168:   })
169: }
