171: // ───────────────────────────── TOVIN ─────────────────────────────
172: function tovin(g) {
173:   if (!g.quests.isActive('espada_rota') && !done(g, 'espada_rota')) {
174:     return N('¡Tú! El de la espada que no debería existir. Esa hoja tiene más años que Valdoria y menos filo que una cuchara. Tráeme tres fragmentos de Hierro Estelar y te forjaré algo que no dé vergüenza. Las vetas brillan junto a las rocas viejas.', {
175:       speaker: 'Tovin', role: 'Herrero de Alda',
176:       choices: [
177:         C('Acepto. Necesito un filo mejor.', 'close', () => { g.quests.start('espada_rota'); }),
178:         C('¿No puedes usar hierro normal?', N('Puedo. Y también puedo coser una herida con hilo de pescar. El hierro estelar canta cuando lo golpeas. Lo normal solo grita.', {
179:           speaker: 'Tovin', role: 'Herrero de Alda',
180:           choices: [C('Buscaré tres fragmentos.', 'close', () => { g.quests.start('espada_rota'); })]
181:         })),
182:         C('Ahora no.', 'close')
183:       ]
184:     })
185:   }
186:   if (has(g, 'espada_rota')) {
187:     const n = g.inventoryCount('hierro_estelar')
188:     if (n < 3) return N(`Te faltan ${3 - n} fragmentos de Hierro Estelar. Mira cerca de las rocas antiguas, en las ruinas y en los cofres. Y no los vendas. Lo digo por experiencia.`, { speaker: 'Tovin', role: 'Herrero de Alda', next: 'close' })
189:     return N('Tres fragmentos. Pesan más de lo que parecen, ¿eh? Dame un momento. *golpea el yunque siete veces* No es superstición: son los siete nombres de la Gema. Ya está. Esto es una espada, no una reliquia oxidada.', {
190:       speaker: 'Tovin', role: 'Herrero de Alda', next: 'close'
191:     })
192:   }
193:   if (done(g, 'espada_rota')) {
194:     return N('La Espada de Vael te queda mejor que a mí. Si la rompes, vuelve. Si la pierdes, no vuelvas. Es broma. Más o menos. *ríe y golpea el yunque una vez más*', {
195:       speaker: 'Tovin', role: 'Herrero de Alda',
196:       choices: [
197:         C('¿Puedes mejorar mi armadura?', N('Con lo que me traes, no. Con lo que traerás de Drakmor, quizá. El metal de allí recuerda el fuego. Y el fuego recuerda a los necios que lo desafiaron.', {
198:           speaker: 'Tovin', role: 'Herrero de Alda', next: 'close'
199:         })),
200:         C('Hasta luego.', 'close')
201:       ]
202:     })
203:   }
204:   return N('El yunque está frío y la cerveza caliente. Un desastre en cualquier orden. Si encuentras hierro estelar, tráelo. Si encuentras una historia, cuéntamela. Prefiero las historias: no hay que afilarlas.', {
205:     speaker: 'Tovin', role: 'Herrero de Alda', next: 'close'
206:   })
207: }
